insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('fdp', 'intermediate', 'module', 'm01-the-schedule-as-a-network', 1, 'a7 integration and commissioning depends on a4 hull conversion, which finishes at 720, and on a5 topsides fabrication, which finishes at 540. What early start does the forward pass give a7?', '["540, the early finish of a5 topsides fabrication, because the pass takes the first predecessor listed on the row and reaches a4 later in the walk.", "390, the early finish of a6 subsea installation, because installation is the last work in the water before commissioning can sensibly begin.", "720, the latest early finish among its predecessors, so a7 runs 720 to 870.", "210, because a successor takes the start of the chain feeding it."]'::jsonb, 2, '300 plus 420 puts a4 at 720 and 720 plus 150 is 870, so an early start of 540 would carry the whole network 180 days early.'),
  ('fdp', 'intermediate', 'module', 'm01-the-schedule-as-a-network', 2, 'EGINA''s eight durations are 0, 210, 300, 420, 330, 180, 150 and 0. Why is the network duration not their total?', '["a2 at 210 and a3 at 300 both start on day 0 and a5 and a6 both start at 210, so parallel work is counted once, along the longest chain, which is 870 days.", "The two milestones of duration 0 are dropped before the sum is taken, because a schedule totals only the rows that carry work.", "The total is reduced by the float the backward pass finds, 180 days on a2, 180 on a5 and 480 on a6, leaving the duration behind.", "The durations are calendar days while the network reports working days, so the total shrinks once the days nobody works are taken out."]'::jsonb, 0, 'The critical path a1, a3, a4, a7, a8 sums 0, 300, 420, 150 and 0 to exactly the 870 days the engine returns.'),
  ('fdp', 'intermediate', 'module', 'm01-the-schedule-as-a-network', 3, 'Subsea installation a6 is 180 days of work and carries 480 days of float. Where does 480 come from?', '["933 less a6''s early finish of 390 and its own 180 days of work, because the calendar span is the room an activity is left before the window closes.", "a5''s 330 days of fabrication added to a7''s 150 days of commissioning, which is the work subsea installation is waiting behind.", "a2''s float of 180 days added to the 300 days of long lead procurement that subsea installation never has to wait for.", "Late start 690 less early start 210."]'::jsonb, 3, 'Float is late start less early start on every row, so a2 reads 180 less 0 and a6 reads 690 less 210, which is 480 days.'),
  ('fdp', 'intermediate', 'module', 'm01-the-schedule-as-a-network', 4, 'a2 detailed engineering feeds a5, whose late start is 390, and a6, whose late start is 690. What late finish does the backward pass give a2?', '["690, the late start of a6 subsea installation, because an activity may finish as late as the last of the activities it feeds will allow.", "390, the earliest late start among its successors, which puts a2''s own late start at 180 and its float at 180.", "870, the network duration, because the backward pass hands every activity the end of the project and then subtracts each duration in turn.", "540, a5''s early finish read in place of its late start."]'::jsonb, 1, 'Taking 690 would give a2 a float of 480 and let a slip in detailed engineering push topsides fabrication past its own late start of 390.'),
  ('fdp', 'intermediate', 'module', 'm01-the-schedule-as-a-network', 5, 'Detailed engineering a2 carries 180 days of float and topsides fabrication a5, which waits on it, carries 180. If a2 runs 180 days late, what is left for a5?', '["Nothing at all: a2 lands on its late finish of 390, a5 then starts at its own late start of 390, and the same 180 days were being read from two rows.", "180 days still, because total float is computed for each activity against the network duration of 870 and is not consumed by a predecessor.", "480 days, the largest float in the network, because a chain running late falls back on the room subsea installation carries.", "150 days, the duration of integration and commissioning, because that is the work standing between topsides fabrication and first oil."]'::jsonb, 0, 'Total float is what an activity can absorb only if nothing ahead of it on the chain has absorbed any first, which is why 180, 180 and 480 do not add up to anything.'),
  ('fdp', 'intermediate', 'module', 'm01-the-schedule-as-a-network', 6, 'A reviewer adds EGINA''s three floats, 180 days on detailed engineering, 180 on topsides fabrication and 480 on subsea installation, and reports the total as the slack in the plan. What is wrong with it?', '["The five activities on the critical path each carry a float of 0 that belongs in the same total.", "Float should be totalled against the calendar span of 933 days rather than against the network duration of 870, so the slack is understated.", "Two of those numbers are the same 180 days seen from two rows, and none of the three is time anything off its own chain can use.", "Subsea installation''s 480 days is a free float and cannot be added to two total floats of 180 until it has been converted to the same measure."]'::jsonb, 2, '480 days says only that a6 may start as late as day 690 and still land on 870, and it says nothing whatever about the hull.'),
  ('fdp', 'intermediate', 'module', 'm01-the-schedule-as-a-network', 7, 'Topsides fabrication is 330 days of work and sits off the critical path, while integration and commissioning is 150 days and sits on it. What decides that?', '["The activity type, since a Commissioning row sits where nothing downstream can absorb a delay while a Fabrication row runs in a yard with slack around it.", "The number of predecessors, since a7 waits on a4 and a5 together while a5 waits on a2 alone, and work fed by two chains cannot be moved.", "The duration, since the critical path is assembled from the longest activities in the schedule until their durations reach the network total of 870 days.", "Float: a5 has 180 days of it and a7 has none."]'::jsonb, 3, 'The chain through a3 and a4 reaches a7 at 720 while a5 is finished at 540, so a5 may slip 180 days and 870 does not move.'),
  ('fdp', 'intermediate', 'module', 'm01-the-schedule-as-a-network', 8, 'A published diamond network returns 10 days with A, B, C and D all critical and two paths, A to B to D and A to C to D. What does that case show?', '["A tie is resolved by marking every activity critical until one route is lengthened, so the four names stand in for a path the engine could not choose between.", "Both routes are 10 days long, so all four activities carry float 0 and a count of critical names is not a count of paths.", "Four critical activities means four paths, and two of them have been merged here because B and C carry the same duration in this network.", "The diamond holds no float anywhere, so it behaves as a single chain of four activities running 10 days from end to end."]'::jsonb, 1, 'The twelve activity chain is the other extreme, 78 days with all twelve critical and one path, because a chain has no alternative route.'),
  ('fdp', 'intermediate', 'module', 'm01-the-schedule-as-a-network', 9, 'Four published activities with no dependencies between them return 7 days, four critical activities and four paths. Why does every one of them read critical?', '["The engine marks every activity critical when it cannot compute float, which is the pre-repair behaviour left in place for unlinked schedules.", "Each of the four is 7 days long, so the four run side by side and every one of them ends the project on the same day.", "Nothing was linked, so each starts on day 0 with nowhere to move, and the schedule is only as long as its longest single activity.", "A schedule with no dependencies is refused as unreadable, and the four names come back attached to the message rather than as a result."]'::jsonb, 2, 'It is the correct answer to the network handed over, and 7 days across four separate paths is a dependency column nobody filled in.'),
  ('fdp', 'intermediate', 'module', 'm01-the-schedule-as-a-network', 10, 'On the published textbook network the engine once reported all six activities critical at float 0. What does the method return once it is run properly?', '["14 days with the critical path at A, B, D and F, and four days of float on each of C and E, which is what the golden reference holds.", "14 days with all six still critical, because the repair corrected the float column and left the critical flag as the engine had always computed it.", "The same six names at float 0, checked against a golden reference computed from the engine''s own pass.", "A refusal, because a network putting every activity on the critical path cannot be told apart from one whose dependency column is empty."]'::jsonb, 0, 'A network whose answer is known from outside the code is the only kind that can show the code is wrong, and this one puts the duration at 14 days.'),
  ('fdp', 'intermediate', 'module', 'm01-the-schedule-as-a-network', 11, 'A schedule is refused with the message: activity b depends on zz, which is not in the schedule. What does that message ask of its reader?', '["Drop the dependency on zz, because an activity that is not in the schedule can constrain nothing and the network then computes cleanly.", "Add an activity called zz with a duration of 0, which takes its place in the logic as a milestone does and leaves every other duration untouched.", "Rename b, because the message names b first and a duplicate activity id is the usual cause of a dependency that cannot be resolved.", "Which activity zz was supposed to be."]'::jsonb, 3, 'Delete the link and a duration comes back happily, computed on a plan that is missing a link somebody meant to type.'),
  ('fdp', 'intermediate', 'module', 'm01-the-schedule-as-a-network', 12, 'A schedule has a waiting on c, c waiting on b and b waiting on a. Why is there no critical path at all?', '["The forward pass returns to its own start and walks the loop twice, so the durations of a, b and c are counted twice and the duration doubles.", "An early start is the latest finish among an activity''s predecessors, and inside the loop no finish is ever known, so there is no ordering to run a pass over.", "Three activities in a cycle all finish at the same time, so all three read float 0 and the engine cannot choose which of them the path runs through.", "The backward pass has no last activity to take a network duration from, although the forward pass completes and reports the length of the loop."]'::jsonb, 1, 'The engine names the three ids in the loop because the only useful fix is deciding which of those links was typed by mistake.'),
  ('fdp', 'intermediate', 'module', 'm01-the-schedule-as-a-network', 13, 'The engine refuses a duration typed as two weeks and accepts a duration of 0. What separates them?', '["A zero is a number somebody typed and takes its place in the logic, as EGINA''s two milestones of duration 0 do, while two weeks is a value the engine will not convert on the author''s behalf.", "A duration of 0 is dropped from the network before either pass runs and so can never be wrong, while a duration written in prose would have to be converted first and then placed somewhere in the logic, which is a decision the engine would be making for the author.", "Two weeks carries no unit the engine recognises, and a 0 is accepted only on a row typed as a Milestone, which is where the type column earns its place.", "The refusal list covers the dependency column alone, so a duration is checked only on a row that some other activity names."]'::jsonb, 0, 'A negative duration is refused the same way, by row and by value: activity a: duration may not be negative: -4.'),
  ('fdp', 'intermediate', 'module', 'm01-the-schedule-as-a-network', 14, 'a8 first oil has a duration of 0 and depends on a6, which finishes at 390, and a7, which finishes at 870. Where does the forward pass put it?', '["At 390, because a milestone consuming no time is placed at the first finish available to it and held there while the rest of the network catches up.", "At 933, the calendar span of the schedule, because first oil is the last dated row and a milestone takes its position from the date column.", "At 870, the later of the two finishes, running from that day to the same day.", "Nowhere inside the passes, because an activity of duration 0 consumes no time and is reported beside the network rather than within it."]'::jsonb, 2, 'EGINA''s milestones are Project sanction and First oil, the two rows of duration 0, and a8 sits at the network duration of 870 days.'),
  ('fdp', 'intermediate', 'module', 'm01-the-schedule-as-a-network', 15, 'What makes the textbook network, the example schedule from 2026-01-01 and the dated four activity plan useful as checks on the engine?', '["Each is small enough to work by hand, so a reviewer recovers the 14 days, the 330 days and the 179 days from the durations without needing a reference at all.", "Each has a duration and a list of critical names computed independently of the engine, at 14 days, 330 days and 179 days, so a wrong answer has somewhere to show.", "Each was produced by the engine and then stored, so a later run disagreeing with the stored 14, 330 or 179 days shows that something in the code has changed since the case was recorded, which is what a check on an engine is for.", "Each carries dates as well as durations, so a calendar span and a network duration can be compared against one another inside a single case."]'::jsonb, 1, 'The dated four activity plan, at 179 days on the path a, b, d, is the smallest of the three that still has an activity sitting off the path.'),
  ('fdp', 'intermediate', 'module', 'm02-dates-that-do-not-move', 1, 'A schedule stored its sanction day by building an instant with new Date from the string 2027-04-01. Which readers were shown a different day?', '["Only readers whose clocks changed between the stored day and the day they opened the plan.", "Every reader west of Greenwich, because that instant is UTC midnight and lands on the day before in their own zone.", "Every reader east of Greenwich, because the instant is local midnight where it was typed.", "None of them, because the string carries no time at all and each reader is shown the stored characters rather than an instant converted into a zone."]'::jsonb, 1, 'The string never said anything about a time, and the moment a day is stored as an instant it acquires a time zone it was never given.'),
  ('fdp', 'intermediate', 'module', 'm02-dates-that-do-not-move', 2, 'A FPSO and a Platform are both sanctioned on 2027-04-01. What first oil does the engine date from each concept?', '["2030-04-01 for both of them, because first oil is a property of the field while the concept decides only what is spent on the way to reaching it.", "2029-04-01 for the FPSO and 2030-04-01 for the Platform, because a platform carries the longer construction of the two concepts at 36 months.", "Dates counted forward from the day the schedule is run, 36 months and 24 months from that day, because the sanction date fixes only the order of the two.", "2030-04-01 at 36 months for the FPSO and 2029-04-01 at 24 months for the Platform."]'::jsonb, 3, 'Each first oil is the concept''s own start date carried forward by the months that concept takes, so 36 months against 24 is a difference in what is required.'),
  ('fdp', 'intermediate', 'module', 'm02-dates-that-do-not-move', 3, 'A FPSO is sanctioned on 2028-02-29. Where does first oil land, and how many months is that?', '["2031-03-01, and still 36 months, because the February three years later has no twenty ninth for the month arithmetic to land on.", "The last day of February in 2031, because a month count beginning on a month end is held to the month end wherever it lands.", "2031-03-01, and 36 months and a day, because the day the calendar could not place is added to the month count rather than dropped from it.", "A refusal, because a sanction on a leap day cannot be carried forward by whole months without choosing a rule the concept never stated."]'::jsonb, 0, 'That is a calendar answering a calendar question; an implementation adding a fixed number of milliseconds would land near 2031-03-01 and drift with every leap year it crossed.'),
  ('fdp', 'intermediate', 'module', 'm02-dates-that-do-not-move', 4, 'Oct 30 to Nov 3 returns 4 days in every zone the engine was run in, including zones whose clocks change inside that window. What produces that?', '["Both ends are counted, and the day that adds makes up the hour lost to the clocks.", "The two ends are converted to UTC before they are subtracted, so the hour the clocks moved is taken off both sides and cancels out between them.", "The span is counted in whole calendar days rather than taken as the difference between two instants.", "A window crossing a clock change is rounded to the nearest whole day, which recovers the 4 days wherever the hour would otherwise have been lost."]'::jsonb, 2, 'An hour is enough to turn a whole number of days into a fraction, and code that truncates then loses a day while code that rounds keeps it.'),
  ('fdp', 'intermediate', 'module', 'm02-dates-that-do-not-move', 5, 'An activity with no readable dates returns a calendar span of null and an empty schedule returns 0. Why are those two answers deliberately different?', '["A span of 0 marks a count that succeeded and null one that was refused, so null carries the message.", "A span of 0 says the schedule has no extent, and null says the extent is unknown because nothing readable was there to measure.", "An empty schedule has no rows that could disagree, while an activity with unreadable dates has one, and null marks that row for somebody to repair.", "Both mean no extent, and the difference between them is one of formatting."]'::jsonb, 1, 'An engine returning 0 for both would report an unfilled form as a project that takes no time at all.'),
  ('fdp', 'intermediate', 'module', 'm02-dates-that-do-not-move', 6, 'EGINA''s network duration is 870 days and the calendar span across the dates typed on the same eight activities is 933. Which inputs produce each figure?', '["870 comes from the durations and the finish to start links with no date taking part, and 933 counts whole days from the earliest typed date to the latest with no duration taking part.", "870 counts the work on the critical path and 933 counts the work on all eight activities, including the three that sit off the path carrying float.", "870 is the span from sanction to first oil and 933 adds the two milestones at the ends, which hold dates of their own and consume no days.", "933 is the same network measured in calendar days and 870 the same network in working days, the difference being the days nobody works."]'::jsonb, 0, 'One says how long the work must take and the other how wide the window is, and 933 less 870 is 63 days.'),
  ('fdp', 'intermediate', 'module', 'm02-dates-that-do-not-move', 7, '933 less 870 is 63 days. What are those 63 days?', '["Contingency somebody set aside against the critical path, which is why it appears in no activity''s float column and belongs to the schedule as a whole.", "The part of subsea installation''s 480 days of float that the typed dates have already consumed, which is why those days belong to that activity.", "Float sitting in the calendar rather than in the logic, belonging to no activity at all, and spent already by typing dates that leave the work room it never asked for.", "Days the schedule spends outside the network, because the milestones of duration 0 hold dates that a network duration of 870 days cannot count."]'::jsonb, 2, 'The 63 days can be spent without any activity slipping and without a warning appearing, because neither figure is measured against the other.'),
  ('fdp', 'intermediate', 'module', 'm02-dates-that-do-not-move', 8, 'EGINA''s milestone list reads Project sanction and First oil. What makes those two rows the milestones?', '["They are the first and last rows of the schedule, and a milestone marks each end of a network whatever duration the row happens to carry.", "They carry dates while the six activities between them carry durations, and a milestone is a dated row with no work underneath it.", "They sit on the critical path at a float of 0, which is what a milestone is: a point in the schedule that cannot be moved at all.", "They are the activities of duration 0."]'::jsonb, 3, 'A milestone takes no days and still holds a position, project sanction at day 0 and first oil at day 870, each running from its day to the same day.'),
  ('fdp', 'intermediate', 'module', 'm02-dates-that-do-not-move', 9, 'A concept carries no start date and is run with no today supplied. What does the engine do?', '["It refuses, with the message that the concept has no start date: enter one, or pass today to date the schedule from.", "It dates the schedule from the day of the run, which is the documented default, and marks that first oil as derived rather than as entered.", "It returns the month count alone, 36 months for a FPSO and 24 for a Platform, leaving the date column empty for the author to fill in.", "It takes the earliest date typed on any activity in the schedule."]'::jsonb, 0, 'The message carries both ways out and the engine takes neither, because a schedule dated from whatever moment the code ran at cannot be reviewed.'),
  ('fdp', 'intermediate', 'module', 'm02-dates-that-do-not-move', 10, 'Why can a first oil date computed from today not be reviewed?', '["It is computed to the instant, so two reviewers in two zones are shown two days.", "It is correct on the day it was computed and wrong on every other day, and nothing in the date column marks where it came from.", "It carries no month count beside it, so a reviewer cannot tell whether the concept behind it was a FPSO at 36 months or a Platform at 24.", "It is rounded to a whole number of days without the direction being recorded."]'::jsonb, 1, 'Run the same plan twice a week apart and the second run disagrees with the first, with nothing in the plan altered.'),
  ('fdp', 'intermediate', 'module', 'm02-dates-that-do-not-move', 11, 'Which figure in EGINA''s schedule holds no date in it at all?', '["The calendar span of 933 days, which counts days rather than naming any of them and so survives a change to the concept''s own start date.", "The month count of 36 months, which is carried forward from a sanction date and comes out the same whichever day the concept is sanctioned on.", "The milestone list, because Project sanction and First oil are positions in the logic and the dates printed beside them are only labels.", "The network duration of 870 days."]'::jsonb, 3, '870 days is a length of work measured from day 0, while every dated figure moves when the concept''s start date moves.'),
  ('fdp', 'intermediate', 'module', 'm02-dates-that-do-not-move', 12, 'Why must a calendar span and a network duration come out of the same arithmetic?', '["Both are printed in one column of the schedule document, so a fraction in either would force the other to be reported to the same precision.", "The calendar span is derived from the network duration by adding the float back on, so a fraction in either would leave the 63 days between them unreadable.", "EGINA''s durations are whole days, 210, 300, 420, 330, 180 and 150 with 0 on the two milestones, and 870 days of work cannot be set beside a window measured in days and a bit.", "The engine compares the two and warns whenever the window is narrower than the work, and a comparison cannot be made across two kinds of number."]'::jsonb, 2, 'A span between dates subtracted as instants comes out an hour wrong across a clock change, and 933 against 870 means something only if both are whole days.'),
  ('fdp', 'intermediate', 'module', 'm02-dates-that-do-not-move', 13, 'A report prints 933 under the heading duration. What does that claim which is not true?', '["That the project holds 933 days of work, when the work is 870 days and 933 is the width of the window the dates sit in.", "That the span was measured from the concept''s start date rather than from an activity''s.", "That the calendar span was counted inclusively at both ends, which is where the difference from the network duration of 870 days comes from.", "That the floats of 180, 180 and 480 days were added into the network duration."]'::jsonb, 0, 'The mirror of it is offering 870 as the gap between sanction and first oil, which claims a window 870 days wide.'),
  ('fdp', 'intermediate', 'module', 'm02-dates-that-do-not-move', 14, 'A plan''s typed dates span fewer days than its network duration. What does the engine report?', '["A refusal, in the way a dependency on an activity that is not in the schedule is refused, because the dates and the logic cannot both hold.", "Both figures, without comment either way, because each is a correct answer to its own question.", "The network duration in place of the span, because the work binds.", "A warning that the window is short, which is the one comparison the engine makes between the calendar and the logic before it prints them."]'::jsonb, 1, 'Nothing reconciles the two automatically, so a window of 933 against work of 870 holds slack and a narrower one is a plan asking for work in days it does not have.'),
  ('fdp', 'intermediate', 'module', 'm02-dates-that-do-not-move', 15, 'Storing a day as an instant and subtracting two instants to measure a length are avoided the same way. How?', '["Convert every stored date to UTC on the way in and back to the reader''s own zone on the way out, so one instant is shown the same way everywhere.", "Store the offset beside the instant, so a length can be corrected for the hour a clock change introduced before it is divided by the length of a day.", "Keep a date as a date, and count in days.", "Round every length to the nearest whole day after the subtraction, which recovers the day that truncating loses across a daylight saving change."]'::jsonb, 2, 'Oct 30 to Nov 3 counts to 4 days in every zone, and the same window subtracted as instants is out by an hour wherever the clocks moved.'),
  ('fdp', 'intermediate', 'module', 'm03-wells-and-rig-days', 1, 'A 12000 ft well is planned vertical, deviated and horizontal in turn. What day counts does the engine return?', '["40 days for all three, because measured depth settles the days while trajectory is carried in the cost of each day rather than in the time.", "40, 46 and 53 days, with all three costing the same 31000000 USD because the extra days are drilled inside one contracted price.", "53 days vertical falling to 40 horizontal, because the horizontal section is drilled faster than the vertical hole above it once the well turns.", "40 days vertical, 46 deviated and 53 horizontal, on the one hole depth."]'::jsonb, 3, 'The cost follows the days at a single price for every day: 31000000, 35650000 and 41075000 USD across those three trajectories.'),
  ('fdp', 'intermediate', 'module', 'm03-wells-and-rig-days', 2, 'At 12000 ft horizontal the engine returns 39 days at low complexity, 53 at medium and 79 at high. The plain 12000 ft horizontal row reads 53 days. What does that tell you?', '["The three complexities are averaged when none is stated, and 53 days is where that average happens to fall for a horizontal well.", "Medium is the complexity the engine assumes when nothing else has been said.", "Complexity is applied after the trajectory and leaves the 53 days unchanged.", "That row was run at low complexity and its 39 days belongs to a shallower well, because a default is never applied to a figure the plan did not carry."]'::jsonb, 1, '39 days against 79 days is the same hole on one word in one field, and 53 days is the word nobody typed.'),
  ('fdp', 'intermediate', 'module', 'm03-wells-and-rig-days', 3, 'EG-01 takes 61 days and EG-02 takes 45. What accounts for the difference?', '["EG-01 is the only well drilled at high complexity, which at 12000 ft is 79 days.", "EG-01 carries its services at 1.5 times the rig while EG-02 is priced on the rig alone, and the extra days are those services being drilled.", "EG-01 is deeper at 14200 ft against 11600 and horizontal against deviated, so two inputs are pushing it up at once.", "EG-01 is 14200 ft against 11600 ft, and depth alone sets the days."]'::jsonb, 2, 'The day count reads depth, trajectory and complexity and nothing else, and EG-01 is the only horizontal well in the campaign.'),
  ('fdp', 'intermediate', 'module', 'm03-wells-and-rig-days', 4, 'EG-03 is a Water Injector and takes 42 days. What does the type column contribute to that figure?', '["Nothing at all: the 42 days comes from 10800 ft on a deviated trajectory, and the type is a label for the reader.", "An injector is drilled to a lower specification than a producer.", "The type sets the complexity, and a Water Injector is taken as low, which at 12000 ft horizontal is the difference between 39 days and 53.", "The type sets the service multiple a producer carries at 1.5 times the rig."]'::jsonb, 0, 'EG-02 at 11600 ft deviated takes 45 days and EG-03 at 10800 ft deviated takes 42, and both are priced at the same 775000 USD a day.'),
  ('fdp', 'intermediate', 'module', 'm03-wells-and-rig-days', 5, 'Why can a drilling campaign not be ranked on measured depth alone?', '["Measured depth is in feet while the days are computed on true vertical depth.", "Depth is the only input the day count reads, so a ranking on depth is sound while a ranking on cost is not, because the rate can move between wells.", "The four wells were drilled under different rig rates, so their day counts cannot be compared until each has been restated at 310000 USD a day.", "A 12000 ft horizontal well takes 53 days against EG-02''s 45 days at 11600 ft, on less hole."]'::jsonb, 3, 'A high complexity horizontal well at 12000 ft takes 79 days, longer than EG-01''s 61 days at 14200 ft.'),
  ('fdp', 'intermediate', 'module', 'm03-wells-and-rig-days', 6, '182 rig days at 310000 USD a day is not EGINA''s campaign cost of 141050000 USD. What is missing from it?', '["The mobilisation and standby between wells, charged once for each rig, which is why a campaign on three rigs costs more than one on a single rig.", "Services, billed at 1.5 times the rig, which put every day of the campaign at 775000 USD all in.", "The days lost while a rig moves between locations.", "The completion of each well, priced separately from the drilling, which is what the plan''s own cost item of 520.0000 million USD is there to cover."]'::jsonb, 1, 'Every one of the four rows divides to the same 775000 USD a day, and a campaign priced on the rig alone understates every well in the same proportion.'),
  ('fdp', 'intermediate', 'module', 'm03-wells-and-rig-days', 7, 'EG-01 at 61 days costs 47275000 USD and EG-04 at 34 days costs 26350000 USD. What do the four wells have in common?', '["An all in day of 775000 USD: a producer and an injector, a vertical well and a horizontal one, are priced the same for each day they take.", "A rate of 310000 USD a day, with the spread between the rows carried by the service multiple, which rises as the trajectory gets harder.", "A cost for each foot drilled, so 14200 ft and 9400 ft price in the same proportion, and the day counts follow from the footage.", "The plan''s development drilling item of 520.0000 million USD, shared across the four wells in the ratio of their measured depths."]'::jsonb, 0, 'Trajectory and depth move the days and the day itself costs the same, so 61 days at 775000 USD is 47275000 USD.'),
  ('fdp', 'intermediate', 'module', 'm03-wells-and-rig-days', 8, 'EGINA''s four wells run 61, 45, 42 and 34 days. What are the campaign totals?', '["182 rig days and 113750000 USD, the four wells priced at the rate the engine carried before it began reading the plan''s own rate.", "95 days and 141050000 USD, because a campaign is reported in the elapsed days it occupies rather than in the days each rig is paid for.", "182 rig days and 141050000 USD, which is 141.0500 million USD.", "182 rig days and 520.0000 million USD, the plan''s own development drilling item, which is the figure carried out of the wells section."]'::jsonb, 2, '47275000 plus 34875000 plus 32550000 plus 26350000 is 141050000 USD, at 310000 USD a day.'),
  ('fdp', 'intermediate', 'module', 'm03-wells-and-rig-days', 9, 'Before the repair the engine returned 113750000 USD for EGINA''s wells although the plan carried 310000 USD a day. What had it been doing?', '["Refusing the plan''s rate as outside the band it searches and falling back on a documented default, which it reported beside the campaign total.", "Pricing every well at a hardcoded 250000 USD a day, with no sign anywhere that the plan''s own rate had been ignored.", "Reading the rate from the first well rather than from the plan.", "Applying the 1.5 service multiple to the rig alone."]'::jsonb, 1, 'The repaired engine reads the rate the plan carries, which is why the same four wells now return 141050000 USD.'),
  ('fdp', 'intermediate', 'module', 'm03-wells-and-rig-days', 10, 'A campaign priced at a stale rig rate still shows EG-01 as the dearest well and EG-04 as the cheapest. Why does that make the error hard to catch?', '["The total is carried out of the wells section and re-derived downstream, so the plan''s own figures disagree and the disagreement reads as rounding.", "The error lands on the days rather than on the money, so 182 rig days is wrong while 141050000 USD is not, and the cost is what gets reviewed.", "A rate error is refused by name in the way a negative capex is, so a reader looks for the message and finds that the campaign computed cleanly.", "Every well moves in the same proportion, so only the total is wrong."]'::jsonb, 3, '113750000 USD stands where 141050000 USD is true, and a plan priced at somebody else''s rate gets approved rather than fixed.'),
  ('fdp', 'intermediate', 'module', 'm03-wells-and-rig-days', 11, 'What campaign length do EGINA''s 182 rig days occupy on one rig, on two and on three?', '["182 days, then 95 days, then 76 days, against 182 rig days of work in every one of the three cases.", "182 days, then 95 days, then 76 days, with the rig days falling to 95 and 76 as the campaign shortens and the rigs share the work out.", "182 days, then half of that, then a third of it.", "182 days in each case, because the wells are drilled in the order they sit in the plan and a second rig only brings the spending forward."]'::jsonb, 0, 'Rig days are the sum of the well durations, 61 plus 45 plus 42 plus 34, and no number of rigs reduces that total by a day.'),
  ('fdp', 'intermediate', 'module', 'm03-wells-and-rig-days', 12, 'On two rigs EGINA''s campaign takes 95 days. How is that reached?', '["The 182 rig days are divided between the two rigs and the result rounded up to the next whole well, because a well cannot be split between them.", "Each rig takes two wells in the order they sit in the plan, EG-01 with EG-03 and EG-02 with EG-04, and the longer of the two rigs sets the campaign.", "EG-01 at 61 and EG-02 at 45 take a rig each, EG-03 at 42 joins the rig free first at 45, and EG-04 at 34 joins the rig carrying 61, which finishes at 95.", "The second rig finishes at 87 days carrying EG-02 and EG-03, and the campaign is reported from the rig that comes free first."]'::jsonb, 2, 'Each well goes to the rig that comes free first, nobody chooses the split, and the two rigs finish at 95 and 87 days.'),
  ('fdp', 'intermediate', 'module', 'm03-wells-and-rig-days', 13, 'Why does no number of rigs bring EGINA''s campaign below 61 days?', '["The 182 rig days spread across a campaign cannot fall below the average of the four wells, which is what the third rig has already reached at 76 days.", "A well cannot be split between rigs, and EG-01 alone is 61 days.", "The three activities carrying float in the schedule network hold the drilling at 61 days, which is the shortest window the plan leaves it.", "A rig beyond the third stands idle, because the wells are dealt out in the order they sit in the plan and the fourth rig is offered none of them."]'::jsonb, 1, 'One rig to two takes the campaign from 182 days to 95 and two to three takes it from 95 to 76, and the floor under all of it is the longest single well.'),
  ('fdp', 'intermediate', 'module', 'm03-wells-and-rig-days', 14, 'EGINA''s four wells cost 141050000 USD on one rig. What do they cost on three?', '["141050000 USD, because the money follows the rig days and adding rigs does not change the 182 days of work at all.", "A third of that, because each rig carries its own share of the 182 rig days and is paid only for the days it actually works.", "More than that, because three rigs stand on rate together.", "113750000 USD, the campaign at the lower of the two rates, because a rig taken for 76 days rather than 182 is contracted differently."]'::jsonb, 0, '182 rig days is a property of the wells, and 76 days is only the elapsed time three rigs buy.'),
  ('fdp', 'intermediate', 'module', 'm03-wells-and-rig-days', 15, 'The plan''s cost item for development drilling reads 520.0000 million USD and the four well campaign comes to 141.0500 million. What should be made of that difference?', '["The campaign figure should replace the cost item, because it is built well by well from depth, trajectory and complexity at the plan''s own rate.", "The cost item should be cut to 141.0500 million USD.", "It is a question to ask, because the two are estimates of overlapping things arrived at two different ways.", "The two should be added, the programme and the rig time it consumes."]'::jsonb, 2, 'The campaign figure is a day count priced at a rate, with no completion detail, no contingency and no standby anywhere in it.'),
  ('fdp', 'intermediate', 'module', 'm04-facilities-sized-and-priced', 1, 'The Egina FPSO card reads a capex of 1363.3524, an annual operating cost of 55.7800 and a decommissioning allowance of 204.5029 million USD at a nameplate of 60000 bopd. What produced those three figures?', '["The plan''s own cost ledger, whose FPSO hull and topsides line of 1180.0000 and mooring and installation line of 170.0000 are summed onto the card and reported there as the facility capex.", "The type and the nameplate alone, each money column being a screening function of those two inputs, so all three move together when the nameplate is revised.", "The FPSO concept''s facilities field of 1350.0000, carried onto the card and grossed up for the vessel''s handling capacities.", "A cost engineer''s estimate written against the concept''s total capex of 2250.0000 and rounded onto the card."]'::jsonb, 1, 'Not one figure on the card was typed by a cost engineer. Move the nameplate to 150000 bopd and the same type returns 2589.2031, 96.6591 and 388.3805.'),
  ('fdp', 'intermediate', 'module', 'm04-facilities-sized-and-priced', 2, 'Moving the FPSO nameplate from 60000 to 150000 bopd multiplies gas handling from 90000 to 225000 Mscf/d and water handling from 48000 to 120000 bopd, a factor of 2.500000. Which other column on the card moves by that same factor?', '["The capex, which rises from 1363.3524 to 2589.2031 because steel and hull volume are bought by the barrel of installed throughput just as separation capacity is.", "The annual operating cost, which rises from 55.7800 to 96.6591 because crew, inspection and marine spread are manned against the capacity that has been installed.", "The decommissioning allowance, which rises from 204.5029 to 388.3805 because removal scope is set by the size of the vessel rather than by the money spent building it.", "None of them: handling capacity is the only part of the card sized in proportion."]'::jsonb, 3, 'Capex moves by 1.899144 and operating cost by 1.732862 over the same step, and the decommissioning allowance follows the capex.'),
  ('fdp', 'intermediate', 'module', 'm04-facilities-sized-and-priced', 3, 'A reader prices the debottlenecked FPSO by taking 1363.3524 and multiplying by the size factor of 2.500000. What has that arithmetic assumed, and what does the engine return instead?', '["An exponent of one on the size factor, where the curve uses 0.7, so the capex factor is 1.899144 and the engine returns 2589.2031 rather than the larger figure proportional scaling gives.", "That capex and operating cost share one exponent, where operating cost uses 0.6 and returns a factor of 1.732862, so the capex should have been read off the operating cost row.", "That the nameplate drives the capex at all, where the driver is the gas handling capacity of 225000 Mscf/d, which is what the curve is actually raised to a power of.", "That the two rows are the same type, where the second is priced off its own base cost, in the way the Deep tie-back holds 184.6717 at a nameplate of 25000."]'::jsonb, 0, 'Raise 2.500000 to the power 0.7 and the answer is 1.899144. Nothing else enters the calculation.'),
  ('fdp', 'intermediate', 'module', 'm04-facilities-sized-and-priced', 4, 'Over the step from 60000 to 150000 bopd the capex factor is 1.899144 and the operating cost factor is 1.732862. Why is the operating cost factor the smaller of the two?', '["The operating cost of 96.6591 is an annual figure spread over the concept''s 20.0000 year life while the capex of 2589.2031 is spent once, so the two factors are taken over different periods.", "The operating cost is a share of the capex in the way the decommissioning allowance is a share of it at 0.150000, and a share of a number that grew by 1.899144 grows more slowly than the number itself.", "Operating cost scales to the power 0.6 and capex to the power 0.7, and the flatter exponent on the same size factor of 2.500000 returns the smaller number.", "The debottlenecked case runs at an oil utilisation of 0.400000, so idle capacity carries no crew or marine spread."]'::jsonb, 2, 'Both factors come from the same 2.500000: to the power 0.7 it is 1.899144 and to the power 0.6 it is 1.732862.'),
  ('fdp', 'intermediate', 'module', 'm04-facilities-sized-and-priced', 5, 'The Deep tie-back holds a capex of 184.6717 at a nameplate of 25000 bopd against the FPSO''s 1363.3524 at 60000. Can the 0.7 exponent account for that gap?', '["Yes: 60000 against 25000 is a larger size step than the one between the two FPSO rows, so raising it to the power 0.7 gives a factor well above the 1.899144 that step returns.", "No: the type changed as well as the size, each type carries its own base cost, and the exponent works only within a type.", "Yes, once the handling capacities are taken in: the tie-back carries 37500 Mscf/d of gas against the FPSO''s 90000, and the curve is raised to a power on capacity rather than on nameplate.", "No: the tie-back is priced from its concept''s capex of 730.0000, not from a curve at all."]'::jsonb, 1, 'Comparing across types tells you what a tie-back is rather than what scale is worth, and the two figures sit far further apart than any exponent on a size ratio would put them.'),
  ('fdp', 'intermediate', 'module', 'm04-facilities-sized-and-priced', 6, 'What does the screening curve behind the FPSO''s capex of 1363.3524 read?', '["A type and a nameplate, and nothing else: it has no water depth, no mooring scope, no local content and no yard order book inside it to interrogate.", "A type, a nameplate and the plan''s peak rate of 60.0000 kbpd, which is what fixes the oil utilisation of 1.000000 that the same card reports.", "A type, a nameplate and the concept''s facilities field of 1350.0000, which anchors the curve so that the two estimates stay close to one another.", "A type, a nameplate and the water depth the facility sits in, which is what separates the FPSO from the Deep tie-back''s 184.6717 at 25000 bopd."]'::jsonb, 0, 'A costed number is built the other way, item by item: the plan''s ledger carries hull and topsides at 1180.0000 and mooring and installation at 170.0000, two lines a person wrote and can defend.'),
  ('fdp', 'intermediate', 'module', 'm04-facilities-sized-and-priced', 7, 'Decommissioning reads 204.5029 on the 60000 bopd FPSO and 388.3805 on the 150000 case, a share of 0.150000 on both rows. What makes the two allowances differ if the share is the same?', '["The exponent is applied to the allowance directly, with removal scope scaling to the power 0.7 in its own right and the 15 percent then read off the answer as a check.", "The share is 0.150000 only after rounding, the two rows carrying different percentages off the type''s base cost.", "The base it is taken from: the allowance is 15 percent of the capex the facility carries, so it inherits that capex''s factor of 1.899144.", "The nameplate enters twice, through the capex and again through the handling capacities."]'::jsonb, 2, 'Nobody told the decommissioning calculation about the power 0.7. It multiplies a capex that already carries the exponent, so the allowance scales that way as well.'),
  ('fdp', 'intermediate', 'module', 'm04-facilities-sized-and-priced', 8, 'Before the repairs made ahead of this course, what did two FPSOs of very different nameplate return for their decommissioning allowance?', '["Figures that differed by the full size factor of 2.500000, because the allowance was taken as a share of the nameplate rather than of any money column at all.", "No figure at all on the larger row, because the allowance was refused by name whenever a nameplate sat above the type''s own base case of 60000 bopd.", "Figures that differed by 1.732862, because the allowance was taken as a share of the annual operating cost, which scales to the power 0.6 rather than to the power 0.7.", "The same figure, because the allowance was 15 percent of the type''s unscaled base cost, so the larger unit looked free to take away."]'::jsonb, 3, 'Treat that as history. The published behaviour now reads 204.5029 against 388.3805 on the two FPSO rows.'),
  ('fdp', 'intermediate', 'module', 'm04-facilities-sized-and-priced', 9, 'The plan''s cost ledger carries a decommissioning provision of 260.0000 million USD as an ABEX line. Where does that provision show up in the screening case?', '["Inside the CAPEX total of 2250.0000, alongside development drilling at 520.0000 and the subsea system at 380.0000, which is how the ledger and the concept come to agree.", "Nowhere: it sits in neither the CAPEX total of 2250.0000 nor the operating cost of 95.0000 a year, and the card''s own allowance of 204.5029 does not enter the screening NPV either.", "Inside the operating cost of 95.0000 a year, spread across the concept''s 20.0000 year life in the way maintenance and integrity at 23.0000 a year is spread.", "In place of the facility card''s allowance of 204.5029, the studio preferring the figure a person wrote whenever the ledger carries a removal line of its own."]'::jsonb, 1, 'The plan holds one removal figure a person wrote and the card holds another a curve produced, and reconciling 260.0000 against 204.5029 is planning work.'),
  ('fdp', 'intermediate', 'module', 'm04-facilities-sized-and-priced', 10, 'Oil utilisation reads 1.000000 on the Egina FPSO, 0.400000 on the debottlenecked case and 2.400000 on the Deep tie-back. What is divided by what?', '["Each facility''s nameplate divided by the largest nameplate on the plan, so the 150000 case reads 1.000000 and the others read as shares of the vessel that carries the most.", "Each facility''s nameplate divided by the peak of the concept it belongs to, which is why the tie-back at a nameplate of 25000 comes out above one against a plan peaking at 60.0000 kbpd.", "The plan''s own peak of 60000 bopd divided by each facility''s nameplate: one numerator and three denominators.", "The plan''s peak divided by the sum of the three nameplates, the studio treating the facilities as one installed capacity and reporting each row''s share of the throughput."]'::jsonb, 2, 'The whole spread of answers comes from the facilities rather than from the production: 60000 into 60000 is 1.000000, into 150000 is 0.400000 and into 25000 is 2.400000.'),
  ('fdp', 'intermediate', 'module', 'm04-facilities-sized-and-priced', 11, 'Gas utilisation reads 0.426667 on the Egina FPSO against a gas capacity of 90000 Mscf/d. Where does the rate on the top of that ratio come from?', '["From the plan''s peak of 60000 bopd at a gas-oil ratio of 640 scf a barrel, which is 38400 Mscf/d, and 38400 into 90000 is 0.426667.", "From the nameplate of 60000 bopd read directly as a gas rate, the studio treating a barrel a day of oil as a thousand standard cubic feet a day of gas.", "From the gas reserves of 70.0000 Bcf spread across the concept''s 20.0000 year life, the plan''s only gas volume.", "From the debottlenecked case''s gas capacity of 225000 Mscf/d, the largest gas handling on the plan."]'::jsonb, 0, 'One numerator of 38400 Mscf/d runs across all three rows: into 225000 it is 0.170667 and into 37500 it is 1.024000.'),
  ('fdp', 'intermediate', 'module', 'm04-facilities-sized-and-priced', 12, 'The Deep tie-back fires Oil Separation Capacity Exceeded at an oil utilisation of 2.400000 and Gas Compression Limits at a gas utilisation of 1.024000. What do the two flags say on their own?', '["That the gas side is the binding constraint, since a compression flag fires before a separation flag and the engine lists the constraints it hit in the order they bind.", "That both sides are over by a comparable amount, since the studio raises a flag only once a utilisation passes the level the other facilities on the plan read against the same peak.", "That the facility needs 2.400000 times its installed oil capacity and 1.024000 times its gas capacity, the flags being the studio''s way of reporting a required duty rather than a breach.", "Only that two limits have been crossed, since a flag carries no magnitude and the ratios beside it hold the size of the problem."]'::jsonb, 3, 'The gas side is over by a hair at 1.024000 and the oil side is nowhere near at 2.400000, and a register of flags with no ratios beside it hides that difference entirely.'),
  ('fdp', 'intermediate', 'module', 'm04-facilities-sized-and-priced', 13, 'Measured against its own concept''s peak of 25.0000 kbpd the Deep tie-back would read an oil utilisation of 1.000000 with no bottleneck at all. Why does the studio not report that figure?', '["Because a utilisation above one is clamped to 1.000000 for reporting, and the studio prints the bottleneck flags instead of the ratio whenever a facility runs over its nameplate.", "Because the throughput comes from the plan being assessed and is the same for every row, so the tie-back is measured at 60000 bopd and reads 2.400000.", "Because the tie-back concept''s peak applies only once a reader selects that concept as the plan''s own.", "Because the peak used is the largest nameplate on the plan, 150000 bopd, rather than a production rate."]'::jsonb, 1, 'Run each facility against the throughput that suits it and the tie-back looks adequate for a plan it cannot carry, which the engine refuses by construction.'),
  ('fdp', 'intermediate', 'module', 'm04-facilities-sized-and-priced', 14, 'The Deep tie-back''s flow assurance score of 3 reads level Medium. A score of 3 on the plan''s risk register reads Low. What accounts for the two readings?', '["Two different scales sharing three words: the flow assurance level is High above 5 and Medium above 2, while the register bands at 20 Critical, 12 High and 6 Medium.", "The register scores a risk as probability times impact while the flow assurance screen adds its hazards up, so a 3 on the screen is worth more than a 3 on the register.", "The flow assurance screen rounds its level up whenever a named hazard is present, and the tie-back carries Hydrates High and Wax Medium against a register row carrying none.", "The register applies its bands only to a scored row, so a 3 falls through to Low as an unscored row does, while the screen bands every score it forms."]'::jsonb, 0, 'The tie-back scores 3 and reads Medium on the screen, while the register''s table puts a probability of 1 and an impact of 3 at a score of 3 and a band of Low.'),
  ('fdp', 'intermediate', 'module', 'm04-facilities-sized-and-priced', 15, 'Run the Deep tie-back on a fluid carrying 12 ppm of H2S and its hazards read Hydrates High, Wax Medium and Corrosion High. What does the screen report for corrosion when the H2S field is left blank?', '["A corrosion entry at the lowest level, the screen treating an empty field as a zero concentration and scoring it as it would a fluid with none.", "An unscored corrosion entry, in the way the risk register reports a row with no probability as Unscored rather than folding it into the Low band.", "Nothing at all: with no figure the corrosion screen cannot fire, so the output is identical to a fluid that was measured and came back sweet.", "No corrosion entry, and a level of Low in place of Medium, the untested hazard being dropped from the score."]'::jsonb, 2, 'The score stays 3 and the level stays Medium either way, so a reader cannot tell from the screen whether the sour gas question was asked and answered or never asked.'),
  ('fdp', 'intermediate', 'module', 'm05-one-risk-scale', 1, 'Subsea tie-in slips carries a probability of 4 and an impact of 5. What score and band does the register give it?', '["A score of 9 and a band of Medium, the two ranks added rather than multiplied.", "A score of 20 and a band of High, a threshold value belonging to the band beneath it, so that Critical begins only once a score passes 20 rather than reaching it.", "A score of 20 and a band of Critical, the score being probability times impact and 20 and above being Critical.", "A score of 108.0000 and a band of Critical, the factor of 0.600000 applied to the cost impact."]'::jsonb, 2, 'The thresholds are 20 and above Critical, 12 and above High, 6 and above Medium and below that Low, and 20 is the boundary value that belongs to the higher band.'),
  ('fdp', 'intermediate', 'module', 'm05-one-risk-scale', 2, 'Hull yard delay scores 12, exactly on a threshold. Which band does it read, and what rule decides that?', '["High, because a score landing on a threshold goes up rather than down, and 12 and above is High.", "Medium, because a threshold opens the band above it only once a score clears it.", "High, because the register assigns the higher of the two neighbouring bands whenever a row''s source is Fabrication, where a schedule slip carries a consequence beyond its own score.", "Medium, because the band is read from the probability of 3 and the impact of 4 separately, and the lower of the two ranks decides which side of the threshold the row falls."]'::jsonb, 0, 'A published case pins the thresholds exactly at 20, 12 and 6 and returns a consolidated score of 68 at Critical 2, High 1, Medium 1 and Low 1 with a health of 46.'),
  ('fdp', 'intermediate', 'module', 'm05-one-risk-scale', 3, 'Subsea tie-in slips holds an impact of 5 against a cost impact of 180.0000 million USD, while Reservoir underperformance holds an impact of 4 against 300.0000. Is one of those rows wrong?', '["Yes: an impact rank is the cost impact placed on the 1 to 5 scale, so the row carrying 300.0000 million USD cannot rank below the row carrying 180.0000 million USD.", "Yes: the ranks are right and the money is reversed between the two rows.", "No: impact ranks the money alone, and a subsurface risk is discounted where a schedule risk is not.", "No: impact is a rank of severity across schedule, cost, reputation and safety at once, and cost impact is a separate column in currency."]'::jsonb, 3, 'The larger money sits on the smaller impact rank and that is allowed, since impact is a rank and not a currency.'),
  ('fdp', 'intermediate', 'module', 'm05-one-risk-scale', 4, 'What does a probability of 4 on the register mean?', '["A four in five chance of the risk landing, which the factor table then rounds down to 0.60.", "The fourth step of a five step scale, which becomes a likelihood only when exposure is priced, through a factor table where 4 keys 0.60.", "A 40 percent chance, the five steps standing for 20 percent each, which the table turns into 0.60.", "A 4 percent chance, which is why the table''s factors sit so far above the step numbers."]'::jsonb, 1, 'A 4 is not 4 percent and not 40 percent, and the factor table is nowhere near the step numbers: 1 gives 0.05, 2 gives 0.20, 3 gives 0.40, 4 gives 0.60 and 5 gives 0.85.'),
  ('fdp', 'intermediate', 'module', 'm05-one-risk-scale', 5, 'The register counts Critical 1, High 1, Medium 1, Low 1 and Unscored 1, and the HSE matrix over the same rows counts critical 1, high 1, medium 1, low 1 and a total of 5. Why do the two agree?', '["The HSE matrix is built from the register''s own band column rather than from the scores, so it copies whatever banding the register has already applied to each row.", "The matrix rescores every row on its own thresholds and the two happen to land together on this register, since no row here sits close enough to a boundary for the scales to part.", "There is one scale in the studio and both surfaces read the same three thresholds.", "The matrix counts only the rows whose source is a safety discipline, and on this register each of the five sources contributes exactly one row, so the two counts match by construction."]'::jsonb, 2, 'Before the repairs made ahead of this course several surfaces carried their own thresholds, and a disagreement between two surfaces is now a bug rather than a matter of interpretation.'),
  ('fdp', 'intermediate', 'module', 'm05-one-risk-scale', 6, 'Host government approval carries an impact of 5, a cost impact of 400.0000 million USD and no probability. What does the register report for it?', '["A band of Unscored, which is not a fifth band but what is reported when no probability means no score could be formed and no threshold applied.", "A band of Low, since a row with no probability scores below every threshold the studio holds.", "A band of Critical, since the impact of 5 is the top of the scale and its 400.0000 the largest money.", "No row at all in the band counts, since a risk that cannot be scored is held back from the register until somebody puts a probability on it."]'::jsonb, 0, 'The count reads Critical 1, High 1, Medium 1, Low 1, Unscored 1, five labels over five rows, and Unscored is the label for a row waiting on a number.'),
  ('fdp', 'intermediate', 'module', 'm05-one-risk-scale', 7, 'The register''s consolidated score is 44. Which figures add to it?', '["20 plus 12 plus 8 plus 4 plus the impact of 5 that the unscored row carries, since a row with an impact still has something to contribute to the total.", "The four band weights of Critical, High, Medium and Low taken in order, which is also the ladder that puts portfolio health at 58 on this register.", "The cost impacts of the four scored rows scaled by their probability factors, which is the same arithmetic that gives a risk exposure of 269.0000 million USD.", "20 plus 12 plus 8 plus 4, the four scored rows and nothing else."]'::jsonb, 3, 'The unscored row forms no score, so it adds nothing to the 44 and is reported separately as unscored risks 1.'),
  ('fdp', 'intermediate', 'module', 'm05-one-risk-scale', 8, 'Take the unscored row out of the register altogether. What happens to a portfolio health of 58?', '["It falls, because health is an average over every row in the register and removing the row that carried the largest cost impact of 400.0000 million USD leaves a worse average behind.", "It still reads 58, because health averages the bands of the scored rows and never saw that row.", "It rises, because the row was being carried in the Low band and a Low row lifts an average built from Critical, High, Medium and Low rows.", "It cannot be read, because health needs every row to carry a probability."]'::jsonb, 1, 'Health reads 58 with the row present and 58 with it absent, and the band count changes only from Unscored 1 to Unscored 0.'),
  ('fdp', 'intermediate', 'module', 'm05-one-risk-scale', 9, 'The register''s Critical row holds a cost impact of 180.0000 million USD against a probability of 4. How much of the risk exposure does that row make up?', '["180.0000 million USD in full, since exposure adds up the cost impacts of every row that carries a probability and leaves out only the row that has none.", "60.0000 million USD, the factor of 0.200000 on the register''s biggest cost impact of 300.0000.", "108.0000 million USD, the factor of 0.600000 applied to its 180.0000, and the largest single contribution to the 269.0000.", "400.0000 million USD, the largest cost impact, the table being keyed on impact here."]'::jsonb, 2, 'The five factors are 0.05, 0.20, 0.40, 0.60 and 0.85, and a probability of 4 keys 0.600000, so 0.600000 times 180.0000 is 108.0000 million USD.'),
  ('fdp', 'intermediate', 'module', 'm05-one-risk-scale', 10, 'Host government approval carries a cost impact of 400.0000 million USD, the largest in the register. What does it add to the exposure of 269.0000 million USD?', '["0.0000, because its probability is missing, so no factor can be keyed and its money never enters the expected value at all.", "A factor of 0.85 applied to its 400.0000, because a row with no probability is priced at the top of the table on the impact of 5 that it does carry.", "400.0000, because an unpriced risk is carried at face value until somebody scores it, which is what keeps the largest money in the register visible.", "5.0000, the missing probability keying the bottom of the table at 0.05."]'::jsonb, 0, 'The single largest number in the register sits outside the single number that claims to summarise the register''s money.'),
  ('fdp', 'intermediate', 'module', 'm05-one-risk-scale', 11, 'The register''s five cost impacts are 180.0000, 240.0000, 300.0000, 25.0000 and 400.0000 million USD. What do they add to, and how does that sit beside the exposure?', '["1145.0000 million USD, which is the worst case the exposure of 269.0000 million USD is the expected half of, the two being the upper and lower bounds of one distribution.", "1145.0000 million USD, which is every risk landing in full, while the exposure of 269.0000 is probability weighted and well below it.", "269.0000 million USD, the cost impacts added once the unscored row''s 400.0000 is left out.", "1145.0000 million USD, which the register reports as its exposure when no factor can be keyed."]'::jsonb, 1, 'Exposure is neither a worst case nor a floor, because nothing here is a distribution: 269.0000 million USD is an expected value and no single risk costs its expected value.'),
  ('fdp', 'intermediate', 'module', 'm05-one-risk-scale', 12, 'A published register returns a consolidated score of 43 with an exposure of 0.0000, and another with every risk Critical returns a consolidated 75, a health of 0 and an exposure of 2.5500. What do the two cases show?', '["Exposure and health are two views of one quantity, so a register that prices at almost nothing has to come back healthy once its cost impact column is filled in.", "An exposure of 0.0000 is the register''s way of refusing to price a set of rows it cannot band, which is why the health of 43 and the health of 0 differ so widely.", "A register can only be compared with another of the same size, so the consolidated scores of 43 and 75 are the readings to use and the money should be left out.", "Exposure reads the cost impacts somebody typed, and health does not read them at all."]'::jsonb, 3, 'A register can be as unhealthy as the scale allows and still price at almost nothing, and an exposure of 0.0000 usually means the cost impact column is empty rather than that the register is safe.'),
  ('fdp', 'intermediate', 'module', 'm05-one-risk-scale', 13, 'Three published registers carry consolidated scores of 6, 9 and 10 and every one of them returns a portfolio health of 80. What does that show about health?', '["It reads the band of each scored risk and averages, so one Medium risk gives 80 whether its score is 6, 9 or 10 and the consolidated score is not an input.", "It is 100 less a penalty on the consolidated score, flat across the range from 6 to 10.", "It is driven by the count of rows rather than by their bands, and all three of those registers hold the same number of rows as one another.", "It rounds to the nearest 10, so consolidated scores of 6, 9 and 10 all report as 80 while a consolidated 12 drops a full band to 50."]'::jsonb, 0, 'Consolidated scores of 12 and 24 both return 50 in the same ladder, which is the same point made twice: health reads bands and the consolidated score adds scores up.'),
  ('fdp', 'intermediate', 'module', 'm05-one-risk-scale', 14, 'A register of three Critical risks returns a portfolio health of 0. One Critical risk beside one Low risk returns 50. What is the difference between those two registers?', '["The Critical rows were mitigated down a band, which is what lifts the average from the floor of 0 and is why the consolidated score falls from 75 to 24.", "Health follows the consolidated score, so 75 reads 0 and 24 reads 50, and any register scoring between those two lands between those two healths.", "A row was added and nothing was mitigated, health being an average that rises when a register grows in its lower bands.", "The three Critical register prices at 2.5500 million USD, too little to support a health reading."]'::jsonb, 2, 'Comparing the health of two registers is only meaningful when they hold a comparable number of rows: a published five row register at Critical 1, High 2, Medium 1 and Low 1 reads 56 against this register''s four scored rows at 58.'),
  ('fdp', 'intermediate', 'module', 'm05-one-risk-scale', 15, 'A published register whose single Medium risk carries a fractional probability returns a consolidated score of 10 and an exposure of 0.0000. Why does the money read zero when the score does not?', '["The row is held as unscored for pricing, the way a row with no probability at all is held.", "The multiplication accepts the fraction and forms a score, but the factor table has no entry for it, so no factor can be keyed and nothing is priced.", "A fractional probability rounds down a step for banding and down to zero for pricing.", "Exposure is reported only when every row carries a probability inside the range 1 to 5."]'::jsonb, 1, 'The multiplication is more forgiving than the scale: a probability typed as text still keys the table and returns an exposure of 4.0000, and a fraction matches nothing.'),
  ('fdp', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'The plan''s network runs 870 days and the dates typed on the same activities span 933 days. What are those two numbers answering?', '["The same question worked two ways, the 933 being the 870 once weekends and holidays are put back into a network that counts working days only.", "How long the work must take, and how long the window somebody typed is, with 63 days of float already spent in the calendar.", "The duration before and after the repairs, the 933 being what the engine returned while every activity read critical.", "The critical path and the longest path through the schedule, the 933 running through the activities with float."]'::jsonb, 1, 'The critical path method returns 870 days along a1, a3, a4, a7 and a8, and the calendar span between the typed dates is 933 days.'),
  ('fdp', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Detailed engineering carries 180 days of float, topsides fabrication 180 and subsea installation 480. What does that float mean, and what did the engine once report instead?', '["Each can slip by that much without moving the end date, and before the repairs made ahead of this course every activity in the schedule read critical at a float of 0.", "Each finishes that far ahead of the 870 day network duration, and the engine once reported the float as a share of the 933 day calendar span instead of in days.", "Each can slip by that much before the critical path moves to another chain, and the engine once carried a1, a3, a4, a7 and a8 as the only activities with any float at all.", "Each is off the critical path by that many days of work, and the engine once reported float only on the activities a reader had typed dates against."]'::jsonb, 0, 'Float is late start minus early start, so a2 and a5 hold 180 days each and a6 holds 480, while a1, a3, a4, a7 and a8 hold 0 and cannot slip at all.'),
  ('fdp', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'A published case of four independent activities with no dependencies typed at all returns a duration of 7 days with all four marked critical. What does that result say about the project?', '["That the four activities are genuinely concurrent and equally urgent, which is the same finding the engine reports when a chain of twelve activities returns a duration of 78 days.", "That the schedule is unreadable and the critical path has fallen back on marking everything critical, which is what the engine did on every network before the repairs.", "Almost nothing: with nothing linked, every activity starts on day 0 and the network is only as long as its longest single activity.", "That the four activities share one resource, since four cannot run at once on one rig."]'::jsonb, 2, 'It is arithmetic rather than a finding about the project, and the method still has to be run on what is actually there.'),
  ('fdp', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'The well campaign takes 182 rig days and costs 141050000 USD. Where does the money come from?', '["The four wells'' measured depths priced at a rate for each trajectory, with 310000 USD a day charged only on the days a rig is actually turning to the right on a producer.", "The plan''s CAPEX total of 2250.0000 million USD apportioned to drilling, which is where the campaign''s share of the development drilling line of 520.0000 is read from.", "A rig rate of 310000 USD a day over the 182 rig days, with services carried separately in the plan''s operating cost of 95.0000 million USD a year.", "A rig rate of 310000 USD a day with services at 1.5 times the rig cost, applied across the four wells."]'::jsonb, 3, 'Every row divides to the same all-in day of 775000 USD, so trajectory and depth move the days while the day itself is priced the same for every well.'),
  ('fdp', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'The same four wells take 182 rig days of work but the campaign runs 95 days on two rigs and 76 days on three. What is the difference between those numbers?', '["Rig days are the work to be done and the campaign length is how long it takes once the work is shared out, each well going to the rig that comes free first.", "Rig days count only the days a rig is on the well while the campaign length adds the moves between locations, which is what puts 95 days against 182 rig days of work.", "The 182 is the campaign on one rig and the shorter figures are what the same campaign costs in days once the rig rate of 310000 USD a day is renegotiated.", "The 182 counts calendar days and the 95 and 76 count working days, which is the same distinction the schedule draws between 933 days and 870 days."]'::jsonb, 0, 'On one rig the campaign is 182 days, on two the rigs finish at 95 and 87 days, and on three they finish at 61, 45 and 76 days.'),
  ('fdp', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'The Egina FPSO carries a capex of 1363.3524 million USD and an oil utilisation of 1.000000 against the plan''s peak. What do those two figures say together?', '["The capex was costed against the plan''s peak of 60.0000 kbpd, which is why the utilisation comes back at exactly 1.000000 rather than at some other ratio.", "The capex follows from a type and a nameplate of 60000 bopd, and the plan''s peak fills that nameplate exactly, so there is no headroom.", "The vessel is fully paid for by the plan it serves, a utilisation of 1.000000 meaning the capex of 1363.3524 million USD is recovered over the concept''s 20.0000 year life.", "The facility is the binding constraint, a utilisation of 1.000000 firing the bottleneck the tie-back fires at 2.400000."]'::jsonb, 1, 'The plan peaks at 60.0000 kbpd, which is 60000 bopd, and the nameplate it is measured against is 60000 bopd, so the ratio is 1.000000 and the decommissioning allowance of 204.5029 follows the capex.'),
  ('fdp', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'The register reports a portfolio health of 58, a risk exposure of 269.0000 million USD and one unscored row carrying the largest cost impact in the register. How do those three readings sit together?', '["Health of 58 already carries the unscored row as a Low, and the exposure of 269.0000 million USD carries its cost impact at the bottom factor of 0.05 in the same way.", "The exposure of 269.0000 million USD is what a health of 58 costs, the two being one reading in two units, with the unscored row left out of both as incomplete.", "The unscored row contributes 0.0000 to the exposure and health reads 58 whether it is present or absent, so the register is the only place all three can be held together.", "Health of 58 is the average of the five rows and the exposure of 269.0000 million USD is their summed cost impacts, so both figures already count every row once."]'::jsonb, 2, 'An unscored risk neither helps nor hurts: it is reported as unscored, and its money never enters the 269.0000 million USD because no probability means no factor.'),
  ('fdp', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'The generated document reports a completeness of 100 percent across nine sections. What has that measured?', '["That the nine sections agree with one another, which is what makes the concept capex of 2250.0000 million USD and the cost ledger''s total of 2250.0000 million USD the same figure.", "That every figure in the plan has been through the engine rather than typed, so the completeness check is what stands behind the headline NPV of 2047.5653 million USD.", "That nine of the nine checks the studio runs came back without a warning, the same check that returns isValid true and an empty list of errors on this plan.", "That each of the nine sections it checks carries something, Field Data through to Risks."]'::jsonb, 3, 'The document reports what is there and what is missing and does not fill gaps: the nine sections are Field Data, Subsurface, Concepts, Wells, Facilities, Schedule, Economics, HSE and Risks.'),
  ('fdp', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'A published cost ledger returns a CAPEX of 574.3000 and an OPEX of 0.5000, and an empty one returns 0.0000 and 0.0000. What do those two cases show about the roll-ups?', '["The roll-up adds only what the ledger holds, so an empty ledger totals zero rather than falling back on any other figure in the plan.", "The roll-up carries a default whenever a ledger is thin, which is why the published case totals 574.3000 while the plan''s own ledger totals 2250.0000 million USD.", "The roll-up is a check on the concept rather than a total, so an empty ledger reports 0.0000 to signal that the concept''s capex should be read instead.", "The roll-up reads the cost items and the facility cards together, which is why a ledger holding neither returns 0.0000 on both lines."]'::jsonb, 0, 'The plan''s own roll-ups are a CAPEX of 2250.0000 and an OPEX of 95.0000 million USD a year, and each is the sum of the lines somebody wrote.'),
  ('fdp', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'A reader adds the document''s headline P50 oil of 130.0000 MMbbl to its P50 gas of 70.0000 Bcf and writes 200.0000. What is wrong with that figure?', '["It has taken a low case for a middle one, since adding a P50 of oil to a P50 of gas gives a figure that has to be labelled P90 once the two distributions are combined.", "It is a number of nothing: the two are different fluids in different units and reserves are totalled one fluid at a time.", "It has doubled the gas, since 70.0000 Bcf is already inside the 130.0000 MMbbl as the associated gas that the plan''s gas-oil ratio of 640 scf a barrel produces.", "It is out by the shrinkage between reservoir and stock tank volumes that separates the 130.0000 from a total."]'::jsonb, 1, 'Oil is MMbbl and gas is Bcf, and a sum of low cases is not the low case of a sum even within one fluid.'),
  ('fdp', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'The plan''s capex is 2250.0000 million USD and its well campaign costs 141050000 USD. How do those two money figures relate?', '["The campaign cost is the drilling share of the 2250.0000, which is why the development drilling line of 520.0000 and the campaign agree once the decimal is moved.", "The campaign cost is the capex of 2250.0000 expressed in whole currency units, the studio printing the same money twice for readers who prefer one unit or the other.", "They are written in different units, plan money in million USD to four decimals and well costs in whole currency units, and neither converts to the other by moving a decimal.", "The campaign cost is outside the capex entirely, since a rig day is an operating cost and belongs in the 95.0000 million USD a year the plan carries."]'::jsonb, 2, 'A peak of 60.0000 kbpd is 60000 bopd and that conversion is exact, but a plan capex and a campaign cost are two different quantities in two different units.'),
  ('fdp', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'An activity carries no readable dates and a concept carries no capex. What does the studio return in each case?', '["A calendar span of 0 for the activity, the same answer an empty schedule gives, and a capex of 100 million USD for the concept, which is the documented default.", "A calendar span taken from the network instead, so the activity inherits the 870 days, and a concept capex read across from the facility card''s 1363.3524 million USD.", "A calendar span of null for the activity, and for the concept a capex of 0.0000 that carries through to a net present value the studio then reports as it stands.", "A calendar span of null for the activity, and a refusal naming the missing figure for the concept."]'::jsonb, 3, 'A capex of 100 million USD was one of four figures substituted silently until the engine was repaired, and writing a plausible number into either gap turns a correct reading into a wrong answer.'),
  ('fdp', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'The Egina FPSO reads an oil utilisation of 1.000000 and the debottlenecked case reads 0.400000 against the same plan. Which of the two is the right answer?', '["Both, since they answer different questions about different facilities, and the work is knowing which nameplate the question named before anything is written down.", "The 1.000000, since the debottlenecked case is a study and the plan is assessed against the facility it actually holds at a nameplate of 60000 bopd.", "The 0.400000, since a utilisation is read against the largest nameplate on the plan, which is what leaves 2589.2031 million USD of capacity to be filled.", "Neither, since a utilisation is only meaningful where a bottleneck fires, as it does on the Deep tie-back at 2.400000 and 1.024000."]'::jsonb, 0, 'A facility reads 1.000000 at a nameplate of 60000 bopd and 0.400000 at 150000 against the same peak, and only one of the two was asked about.'),
  ('fdp', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'The concept''s capex is 2250.0000 million USD, the cost ledger totals 2250.0000 million USD and the facility card carries 1363.3524 million USD. What is a reader supposed to do with three figures for overlapping scope?', '["Take the ledger''s 2250.0000 million USD, since the concept agrees with it and two estimates against one settle which of the three methods the plan should be read on.", "Reconcile them, since three estimates of one cost by three methods is a question somebody has to answer before sanction rather than a number to average.", "Take the facility card''s 1363.3524 million USD, since a screening curve is the one figure no reader has adjusted.", "Treat them as one estimate seen three ways, the card covering the facilities and the others the whole development."]'::jsonb, 1, 'The card''s 1363.3524 is a screening estimate, the ledger is a line by line total and the concept holds drilling, facilities and subsea, and the plan''s own facilities field reads 1350.0000.'),
  ('fdp', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'The document''s headline figures read P50 oil 130.0000 MMbbl, P50 gas 70.0000 Bcf, total CAPEX 2250.0000, NPV 2047.5653 and IRR 29.5998, with 4 wells. Which of them carries a P label correctly?', '["The oil, the gas and the CAPEX, since the capex of 2250.0000 is itself a screening distribution and the document reports its middle case alongside the volumes.", "The oil, the gas and the NPV, since a net present value of 2047.5653 is carried at the same case as the reserves it was computed from and is labelled with them.", "The oil and the gas, since a P label belongs to a reserves distribution one fluid at a time.", "None of them, since a P label belongs to a distribution across reservoirs and the document reports one field, so its volumes are single figures rather than percentiles."]'::jsonb, 2, 'A capex, a rate, a cost, a duration, an index or a ratio never takes a P label, so the 2250.0000, the 2047.5653 and the 29.5998 carry none.'),
  ('fdp', 'intermediate', 'final', null, 1, 'Hull conversion slips 60 days on a network that returns 870 days, and the Egina FPSO card reads a capex of 1363.3524, an operating cost of 55.7800 and a decommissioning allowance of 204.5029 million USD. Which of those three figures moves with the slip?', '["None of them, because the card reads a type and a nameplate of 60000 bopd and no duration at all, while first oil does move, since hull conversion sits at a float of 0.", "All three, because the allowance is 15 percent of a capex that a longer build carries more of, and the operating cost of 55.7800 follows the same curve at the power 0.6.", "The operating cost alone, because 55.7800 is an annual figure and 60 more days of construction is 60 more days of it standing before the vessel earns anything at all.", "None of them, and first oil holds as well, because hull conversion carries 180 days of float in the way detailed engineering and topsides fabrication do."]'::jsonb, 0, 'a4 sits on the critical path with a late start of 300 and a float of 0, so a slip on it moves 870; the card''s three money columns are a curve on a type and a nameplate.'),
  ('fdp', 'intermediate', 'final', null, 2, 'Subsea installation is 180 days of work, the smallest real piece on EGINA''s schedule, and it carries 480 days of float. What produced that figure?', '["The sum of the floats along its own chain, since a2 carries 180 days of float ahead of it and those days are added to whatever a6 can absorb on its own account.", "The gap between the calendar span of 933 days and the network duration of 870 days, spread across the three activities that sit off the critical path.", "Its late start of 690 less its early start of 210, with the late finish of 870 coming from a8, which also waits on the far longer chain through a4 and a7.", "The 870 day duration less the 420 days of hull conversion, since the longest single activity in a network sets the room that every shorter one is given."]'::jsonb, 2, 'Float is late start less early start, so 690 less 210 is 480, and a6 may start as late as day 690 and still land on 870.'),
  ('fdp', 'intermediate', 'final', null, 3, 'A schedule where a waits on c, c waits on b and b waits on a returns the message that the schedule has a dependency cycle through a, b and c. Why is that a refusal rather than a duration?', '["The pass would keep adding durations to itself without ever reaching an end, so the engine stops at a fixed iteration count and reports the ids it was still holding at that point.", "The forward pass needs an activity whose predecessors are all known, and inside the loop none of the three ever is, so there is no ordering to walk and no pass to run.", "A cycle makes every activity critical at float 0, and the engine declines any network whose critical list holds every row in the schedule.", "The duration would be right and only the critical path through the loop ambiguous, so the message stands in place of the path while the duration itself is left unreported."]'::jsonb, 1, 'Naming the three ids is the useful part, because the fix is deciding which of those links was typed by mistake, and dropping one quietly computes a duration for a plan nobody wrote.'),
  ('fdp', 'intermediate', 'final', null, 4, 'A published case of four activities with no dependencies at all returns a duration of 7 days with all four critical across four separate paths. What does critical mean there?', '["That the engine could not read the dependency column at all and fell back on marking every row critical at float 0, which is exactly the behaviour repaired before this course.", "Only that nothing gave any of them anywhere to move, since with no links typed every activity starts on day 0 and the schedule is as long as its longest single activity.", "That the four activities share one path of 7 days, because unlinked activities are chained in the order they happen to sit in the schedule.", "That each of the four is itself 7 days long, which is why none of them can absorb a slip without moving the end of the project."]'::jsonb, 1, 'It is the correct answer to the network it was handed, and it reports four paths, one per activity; a schedule where nothing is linked looks healthy and is not.'),
  ('fdp', 'intermediate', 'final', null, 5, 'A planner points at detailed engineering''s 180 days of float and says the four well campaign, 182 rig days on a single rig, will fit inside it. What is wrong with that?', '["Nothing, provided the campaign is run on two rigs at 95 days, which is the figure that fits inside 180 days of float with a fortnight left over.", "The float to use is 480 days rather than 180, since subsea installation is the activity the drilling would run beside and it is the one carrying room.", "The campaign is 182 days of elapsed time and the float is 180 days of work, so the two are different quantities and the rig days have to be restated first.", "Float belongs to its own chain, and the campaign is not an activity in the network at all."]'::jsonb, 3, 'Total float is what one activity can absorb only if nothing ahead of it on its chain absorbs any first, and EGINA''s eight activities carry no drilling row for a campaign to sit in.'),
  ('fdp', 'intermediate', 'final', null, 6, 'The generated document lists HSE and Risks as two separate sections of the nine it checks. Does a plan carrying both of them band its risks twice?', '["No, because one scale runs the register, the HSE tab and the matrix, so both sections read the same thresholds and cannot disagree with each other.", "Yes, because the HSE tab holds thresholds of its own, which is why one row can read High on one section and Medium on the other and a reader takes the worse of the two.", "Yes, because the hazard screen that bands High above 5 and Medium above 2 is what the HSE section reports, and the register bands the same rows at 20, 12 and 6.", "No, because only the Risks section bands anything at all: the HSE section counts the rows naming a safety source, which is why the two totals agree at five."]'::jsonb, 0, 'Before the repairs made ahead of this course several surfaces each carried their own thresholds, so a disagreement between two of them is now a bug rather than a reading.'),
  ('fdp', 'intermediate', 'final', null, 7, 'The four well campaign occupies 95 elapsed days on two rigs. What does the studio need before those 95 days can be shown as a start date and an end date?', '["Nothing, since a campaign is dated from the day the plan is run, which is why the layout reports elapsed days rather than rig days in the first place.", "The 182 rig days, since a date column is built from the work rather than from the elapsed time somebody plans around, and the two rigs finish at 95 and 87 days.", "A day somebody typed, since nothing is read from the machine''s clock and a concept with no start date is refused rather than dated from today.", "The network duration of 870 days, since every dated figure anywhere in the schedule is measured out from the same day 0 that the forward pass starts counting at."]'::jsonb, 2, 'A span is counted in whole calendar days and every date in EGINA is stated somewhere, so a date from a clock is right on the day it was computed and wrong on every other.'),
  ('fdp', 'intermediate', 'final', null, 8, 'An activity whose dates cannot be read returns a calendar span of null, and the document still counts Schedule among the nine sections it reports present. Is that a contradiction?', '["No: completeness asks only whether a section carries something, and null is the honest answer to a different question, so neither figure is filling a gap.", "Yes: an unreadable date should drop the plan to 89 percent in the way a plan with no economics written does, and the null is the check the document missed.", "Yes: null is what the count returns before a section has been read at all, so a Schedule reported present has already overwritten that null with a span of 0.", "No: the document reads the network duration of 870 days rather than the typed dates, so the Schedule section never sees the unreadable row and the null never reaches it."]'::jsonb, 0, 'The document reports what is there and what is missing without filling a gap, and null says the extent is unknown where 0 would say the schedule has no extent.'),
  ('fdp', 'intermediate', 'final', null, 9, 'A FPSO sanctioned on 2028-02-29 reaches first oil on 2031-03-01, and the engine still reports 36 months. Why does the date land on the first of March?', '["The engine adds a fixed count of milliseconds for the 36 months and the extra leap day pushes the result past midnight, which is why the month count between the two dates still reads 36.", "First oil moves to the next working day whenever the month arithmetic lands on a date the calendar does not carry, which adds a day to the span.", "The concept carries 36 months from sanction, and the engine dates a leap day start from today, so the answer moves with the day the plan was run.", "The sanction sits on the last day of a February that has a twenty ninth, the February three years later does not, and month arithmetic on a calendar lands on the following day."]'::jsonb, 3, 'A FPSO sanctioned 2027-04-01 reaches 2030-04-01 at the same 36 months, and an implementation counting milliseconds drifts with every leap year it crosses.'),
  ('fdp', 'intermediate', 'final', null, 10, 'A concept with no start date, run with no today supplied, is refused and told to enter one or pass today to date the schedule from. Why can the engine take neither way out itself?', '["The concept''s 36 months are measured from its sanction date, and with no sanction typed the engine cannot tell a FPSO from a Platform at 24 months.", "Both ways out need somebody to choose a day and be able to state it, and a schedule dated from the moment the code ran disagrees with itself a week later with nothing altered.", "Dating from today would be correct enough, but the calendar span of 933 days would then have to move with it, and the engine will not shift a figure a reader has already seen.", "A missing start date is a completeness failure rather than an input error, so the plan drops to 89 percent and the schedule is simply left undated."]'::jsonb, 1, 'A first oil computed from a clock is right on the day it was computed and wrong on every other, and a plausible date in a date column carries no mark saying where it came from.'),
  ('fdp', 'intermediate', 'final', null, 11, 'Reading 2027-04-01 as an instant rather than as a calendar date showed one stored string as two different days. Which readers saw the earlier day, and why did nothing look broken?', '["Only readers in zones that change their clocks, because the offset shifts by an hour inside the window and a whole number of days becomes a fraction.", "Everyone east of Greenwich, because local midnight there falls after UTC midnight and the stored instant is then rounded down to the preceding day.", "Everyone west of Greenwich, because UTC midnight falls on the day before there, and sanction, first oil and every milestone moved together so each reader saw a consistent schedule.", "Only the reader who typed the date, because the stored value keeps its author''s zone while every other reader is shown the plan converted into their own."]'::jsonb, 2, 'The string never said anything about a time, and the disagreement surfaces only when two readers quote a date to each other.'),
  ('fdp', 'intermediate', 'final', null, 12, 'The rig rate of 310000 USD a day is a figure the plan carries and the FPSO card''s capex of 1363.3524 comes off a screening curve. Which of the two can be argued about with a contract in hand?', '["The capex, since 1363.3524 is printed to four decimals against a rate typed as a round 310000, and the more precise figure is the one a quote can be set against.", "Both, since the curve is fitted to yard prices and the rate comes from the rig market, so a commercial negotiation moves each of them the same way.", "Neither, since both are engine outputs, and the ledger lines of 1180.0000 for hull and topsides and 170.0000 for mooring and installation are the only figures a contract reaches.", "The rate, which is negotiated and dated and belongs to the plan, while the curve reads a type and a nameplate and has never seen a shipyard quote."]'::jsonb, 3, 'Before the repair every well was priced at a hardcoded 250000 USD a day whatever the plan carried, which is why the rate an answer was computed at is read before the answer.'),
  ('fdp', 'intermediate', 'final', null, 13, 'EG-02 is 11600 ft and takes 45 days, while a 12000 ft horizontal well takes 53. What does that say about ranking a campaign by depth?', '["That depth alone does not order the days, because trajectory moves them as well: the same 12000 ft hole is 40 days vertical, 46 deviated and 53 horizontal.", "That the ordering holds and EG-02 is the exception to it, since a well drilled from an existing slot carries fewer days than a fresh hole at the same depth.", "That the day count is settled by complexity alone, and the engine assumes high complexity on a 12000 ft hole, which is the 79 day case in the table.", "That a producer takes longer than an injector at the same depth, which is why EG-03 at 10800 ft returns 42 days against EG-02''s 45."]'::jsonb, 0, 'A high complexity horizontal at 12000 ft takes 79 days, longer than EG-01''s 61 days at 14200 ft, on less hole.'),
  ('fdp', 'intermediate', 'final', null, 14, 'A campaign priced at a stale rig rate returns 113750000 USD where 141050000 USD is true, with all four wells still in the right order. Which row of the risk register carries that?', '["Logistics congestion, the Operations row banded Low at a score of 4, whose cost impact of 25.0000 million USD is where an error in a commercial term lands.", "None of them, because a register holds the rows somebody wrote and scored, and a silent pricing error raises no row, no band and no flag anywhere.", "Hull yard delay, the Fabrication row banded High at a score of 12, since a commercial rate that was never read is a yard and fabrication exposure by source.", "The unscored row, since Host government approval is what the register reports whenever a figure is missing rather than wrong."]'::jsonb, 1, 'A refusal would be easier to live with: a negative capex is refused by name and gets fixed within the hour, while a plan priced at somebody else''s rate computes cleanly.'),
  ('fdp', 'intermediate', 'final', null, 15, 'On two rigs EGINA''s four wells take 95 days against 182 rig days of work. Where does 95 come from?', '["From dividing the 182 rig days between the two rigs and rounding the answer up to a whole day, since a rig cannot be stood down part way through a shift on a well.", "From the longest well at 61 days plus the shortest at 34 days, since the two rigs are run in step with each other and the campaign closes when the slower pair finishes.", "Each well goes to the rig free first: EG-01 at 61 and EG-02 at 45 take a rig each, EG-03 at 42 joins the rig free at 45, and EG-04 at 34 joins the rig carrying 61.", "From an optimiser balancing the rigs, which pairs 61 with 34 and 45 with 42 to bring both as close to 87 days as whole wells allow."]'::jsonb, 2, 'The rigs finish at 95 and 87 days, and a well cannot be split, so the arithmetic is a packing problem in whole wells rather than a division.'),
  ('fdp', 'intermediate', 'final', null, 16, 'Priced at 250000 USD a day the same four wells return 113750000 USD against 141050000 USD at the plan''s own rate. Why is that error hard to catch in the table?', '["The engine flags a rate it did not read from the plan, and the flag sits on the campaign total rather than on any row, where a reader scanning wells will miss it.", "The two totals differ by less than the spread between the trajectories, so the difference falls inside a range that the day count could never have narrowed.", "Every row moves in the same proportion, so the deepest well is still the dearest and only the total is wrong, and totals are what leave the wells section.", "The costs are printed to the unit, so the change lands in the digits after the first few and leaves the leading figures of every well undisturbed."]'::jsonb, 2, 'Before the repair every well was priced at a hardcoded 250000 USD a day whatever the plan carried, so a plan entering 310000 got 113750000 back with no sign of it.'),
  ('fdp', 'intermediate', 'final', null, 17, 'Moving the FPSO''s nameplate from 60000 to 150000 bopd is a factor of 2.500000 in size and 1.899144 in capex. What decides the second figure?', '["The exponent alone: 2.500000 raised to the power 0.7 is 1.899144, so the capex reads 2589.2031 rather than the larger figure proportional scaling would give.", "The type, since both rows belong to the same FPSO family and that family''s own base cost is added once before the size ratio is applied to whatever remains of it.", "The gas and water handling capacities, which multiply by 2.500000 in exact step with the nameplate and drag the capex up by less than the full size factor of 2.500000.", "The decommissioning allowance of 204.5029, which rides inside the capex figure at 15 percent of it and damps the rise in the capex as the nameplate is grown."]'::jsonb, 0, 'Operating cost uses a flatter exponent of 0.6, giving 1.732862 from 55.7800 to 96.6591, and a reader multiplying by 2.500000 overprices the debottlenecked case.'),
  ('fdp', 'intermediate', 'final', null, 18, 'Decommissioning is 0.150000 of capex on all three facilities and still moves by 1.899144 between the two FPSO rows. How does a flat percentage carry the size exponent?', '["The percentage is taken on the type''s own unscaled base cost and is then rescaled by the nameplate ratio, which is the behaviour the engine now publishes.", "It is a share of a capex that already carries the exponent, so 204.5029 and 388.3805 stand in the same ratio as 1363.3524 and 2589.2031.", "The share is 0.150000 on the FPSO rows only, and the tie-back''s 27.7007 against 184.6717 uses a separate allowance written for a subsea system.", "The allowance reads the plan''s own decommissioning provision of 260.0000 and apportions it across the facilities in proportion to their nameplates."]'::jsonb, 1, 'Before the repairs the allowance was 15 percent of the unscaled base cost, so two FPSOs of very different nameplate returned the same removal figure.'),
  ('fdp', 'intermediate', 'final', null, 19, 'The Deep tie-back reads an oil utilisation of 2.400000 and a gas utilisation of 1.024000, and a bottleneck fires on each side. What is a flag on its own not telling you?', '["By how much the limit was crossed: the gas side is over by a hair at 1.024000 and the oil side is at 2.400000, and both flags read exactly the same.", "Which facility the flag belongs to, since bottlenecks are reported for the plan as a whole and the two FPSO rows carry the same two entries beside them.", "Whether the limit is crossed at peak or across the profile, since the engine reads the whole shape and flags any year in which either ratio passes one.", "That a utilisation above one is a reading rather than an error, since the engine clamps the ratio at full and reports the overrun only through the flag."]'::jsonb, 0, 'One numerator and three denominators, 60000 bopd against each nameplate and 38400 Mscf/d against each gas capacity, so the ratios carry the size of the problem.'),
  ('fdp', 'intermediate', 'final', null, 20, 'Run the Deep tie-back against the tie-back concept''s own peak instead of the plan''s and its oil utilisation reads 1.000000 with no bottleneck. Why does the engine refuse that?', '["A nameplate of 25000 sits below the screening tier''s floor, so the engine measures every subsea tie-back against the largest nameplate the plan holds.", "The concept''s peak is a screening shape rather than a forecast, so the engine substitutes the gas rate of 38400 Mscf/d for it on every facility row.", "Two concepts cannot be assessed at once, so the tie-back is held at the FPSO''s utilisation of 1.000000 until one concept has been selected.", "The throughput belongs to the plan being assessed, the same 60000 bopd for every row, so a facility measured against the rate that suits it looks adequate for a plan it cannot carry."]'::jsonb, 3, 'The plan''s peak of 60.0000 kbpd is 60000 bopd for all three rows, which is why the FPSO reads 1.000000, the debottlenecked case 0.400000 and the tie-back 2.400000.'),
  ('fdp', 'intermediate', 'final', null, 21, 'The Deep tie-back gains Corrosion High when the fluid carries 12 ppm of H2S and shows nothing for corrosion when the field is blank. What cannot be read off that output?', '["Whether the hazard is High or Medium, since the corrosion screen grades on the measured concentration and 12 ppm sits near the boundary between them.", "Which facility carries the hazard, since the list is written against the fluid and the same entries are returned for every facility on the plan.", "Whether the sour gas question was asked and answered or never asked at all, because the screen fires at any H2S above zero and a blank field leaves the same absent entry a clean one does.", "Whether the score of 3 came from the configuration or from the fluid, since a subsea tie-back adds 3 and oil below 25 API adds 2 to the same total."]'::jsonb, 2, 'The screen separates a measured field from an unmeasured one rather than one sour field from another, and the register at least has the word Unscored for a row waiting on a number.'),
  ('fdp', 'intermediate', 'final', null, 22, 'The FPSO card''s capex of 1363.3524 is a screening figure, and the plan''s ledger carries hull and topsides at 1180.0000 with mooring and installation at 170.0000. What can be done with the ledger that cannot be done with the card?', '["Its lines can each be rescaled to a new nameplate, since every one of them carries the same power 0.7 exponent that the screening curve applies only to a total figure at the end.", "Its lines can be interrogated, because a person wrote each of them and can defend it, while the curve reads a type and a nameplate and holds nothing inside to question.", "Its lines enter the screening economics, while the card''s capex is reported beside the plan and left out of them in the way the ABEX line is left out.", "Its lines carry contingency and standby, which is what separates 1363.3524 from the 1350.0000 the concept holds in its facilities field."]'::jsonb, 1, '1363.3524 is an output of two inputs and it moves the moment somebody revises the nameplate, with no new engineering behind the change.'),
  ('fdp', 'intermediate', 'final', null, 23, 'Subsea tie-in slips scores 20 and Hull yard delay scores 12. Which bands do they take, and what rule decides?', '["Critical and High, because the thresholds read 20 and above, 12 and above and 6 and above, so a score landing exactly on a threshold goes up rather than down.", "High and Medium, since a threshold opens the band above it and a score has to pass 20 before the Critical label can be applied to the row that carries the score.", "Critical and High, decided by the impact ranks of 5 and 4 rather than by the scores, since the band is read from impact while the score orders the register within that band.", "Critical and Critical, since a Schedule risk and a Fabrication risk both bear on the date of first oil, and the register promotes any risk that touches an activity sitting on the critical path."]'::jsonb, 0, 'A published case pins the thresholds at 20, 12 and 6 and returns Critical 2, High 1, Medium 1 and Low 1 at a consolidated 68 and a health of 46.'),
  ('fdp', 'intermediate', 'final', null, 24, 'Host government approval carries an impact of 5 and a cost impact of 400.0000 million USD, the largest in the register, and contributes 0.0000 to an exposure of 269.0000. What produced that?', '["A Regulatory risk is left out of exposure by source, since the register prices only the risks a project team can mitigate from its own budget.", "The engine caps any one contribution at the largest scored one, 108.0000 from Subsea tie-in slips, so a cost impact above that is reported and not priced.", "An impact of 5 keys a factor of 0.85 and the product is carried into health instead, which is why health reads 58 with the row present and absent.", "Its probability is missing, so no factor can be keyed from the table that turns a rank into a likelihood, and with no factor the money never enters."]'::jsonb, 3, 'The four scored contributions of 108.0000, 96.0000, 60.0000 and 5.0000 add to 269.0000, and the largest money in the register sits outside the number that summarises its money.'),
  ('fdp', 'intermediate', 'final', null, 25, 'The register''s five cost impacts add to 1145.0000 million USD and its exposure reads 269.0000. What is the 269.0000, and what is it not?', '["The contingency to fund, since the difference from 1145.0000 is the part the register''s own mitigations are expected to remove before sanction.", "An expected monetary value, each cost impact multiplied by the factor its probability keys, and neither the worst case of everything landing nor a floor, because nothing here is a distribution.", "The worst case with the unscored row excluded, since a risk with no probability cannot be assumed to happen and its 400.0000 is held back.", "The sum of the Critical and High contributions of 108.0000 and 96.0000, grossed up for the Medium and Low rows the engine treats as noise."]'::jsonb, 1, 'No risk costs its expected value, it costs its cost impact or it costs nothing, and an exposure of 0.0000 usually means the cost impact column is empty.'),
  ('fdp', 'intermediate', 'final', null, 26, 'The FPSO card carries a decommissioning allowance of 204.5029 and the plan''s ledger carries an ABEX line of 260.0000 million USD. Where do those two figures sit in roll-ups of 2250.0000 CAPEX and 95.0000 OPEX?', '["The 260.0000 is inside the CAPEX total and the 204.5029 is left out of it, which is how the ledger comes to agree with the concept''s own capex of 2250.0000 to the decimal.", "The 204.5029 is inside the CAPEX total of 2250.0000 and the 260.0000 is spread across the operating cost of 95.0000 a year over the concept''s own 20.0000 year life.", "In neither: the roll-ups add the CAPEX and OPEX lines the ledger holds, so one removal figure sits outside the totals and the other was never in the ledger at all.", "Both sit inside the OPEX total of 95.0000 a year, which is why that figure stands well above the card''s own annual operating cost of 55.7800 for the same vessel."]'::jsonb, 2, 'The plan holds one removal figure a person wrote and the card holds another a curve produced, and the screening case carries capex and operating cost only.'),
  ('fdp', 'intermediate', 'final', null, 27, 'A published register of five rows reading Critical 1, High 2, Medium 1 and Low 1 returns a health of 56, and EGINA''s four scored rows return 58. Why is that comparison unsafe?', '["The five row register carries an exposure of 48.1000 against EGINA''s 269.0000, and health is weighted by the money each band contributes to it.", "EGINA holds an unscored row and the published register does not, so EGINA''s 58 is averaged over five rows against the other register''s four.", "A consolidated 56 sits below EGINA''s 44 on the scale health inverts, so the two numbers are reported on two different bases.", "Health averages over the scored rows, so a register rises as it grows in its lower bands, and the five row register is the worse of the two by a margin an average carries badly."]'::jsonb, 3, 'Every risk Critical returns 0 and one Critical with one Low returns 50, and nothing was mitigated between those two registers: a row was added.'),
  ('fdp', 'intermediate', 'final', null, 28, 'The Egina FPSO card returns an annual operating cost of 55.7800 million USD and the document''s roll-up reports a total OPEX of 95.0000. Which of the two is the plan''s operating cost?', '["The 55.7800, since it is the only one of the two derived from the facility the plan actually holds, and the ledger lines of 72.0000 and 23.0000 are provisional entries somebody has yet to firm up.", "The 95.0000, the sum of the operating lines somebody wrote at 72.0000 for operations and logistics and 23.0000 for maintenance and integrity, while 55.7800 is a curve output.", "Both, once the Deep tie-back''s 9.8963 is added to the FPSO''s 55.7800, since the roll-up is the sum taken across whichever facility cards a plan happens to carry.", "Neither, since the card''s figure is annual and the roll-up''s covers the whole life, so the two need putting on one basis before either can be called the plan''s."]'::jsonb, 1, 'The roll-up adds the cost items the ledger holds and nothing else, and the card''s 55.7800 is a screening function of a type and a nameplate of 60000 bopd.'),
  ('fdp', 'intermediate', 'final', null, 29, 'A probability typed as text keys the factor table and gives an exposure of 4.0000, a fractional probability scores 10 but gives an exposure of 0.0000, and a probability outside 1 to 5 gives a consolidated 24. What is the common lesson?', '["The multiplication is more forgiving than the scale, so a register returns a banded and healthy looking answer on a probability the exposure table cannot price, and the discipline is at the keyboard.", "The engine declines any probability it cannot band, so each of those three registers reports its rows as unscored and prices none of them.", "A probability outside the range is clamped to the nearest end of the scale, which is why the out of range case reads one Critical and one Low.", "The factor table reads text and fractions alike, so all three carry an exposure and the differences between them are rounding in the fourth decimal."]'::jsonb, 0, 'The fractional case returns a Medium at a consolidated 10 with an exposure of 0.0000, because it matches nothing in a table where 1 keys 0.05 and 5 keys 0.85.'),
  ('fdp', 'intermediate', 'final', null, 30, 'The document reports completeness of 100 percent across nine sections while the register carries an unscored row and the schedule''s window is wider than its network. What does that 100 percent claim?', '["That the plan validates, since isValid true and an empty error list are what the completeness percentage is computed from, one section at a time.", "That every figure in the nine sections was read from the engine rather than typed by hand, which is what the repairs before this course made the check test for.", "Only that each of the nine carries something: Field Data, Subsurface, Concepts, Wells, Facilities, Schedule, Economics, HSE and Risks are present, and completeness has no view on whether their numbers agree.", "That the sections reconcile, since a plan whose capex total and cost ledger disagree loses a section and cannot reach the full mark."]'::jsonb, 2, 'The register still reads Unscored 1 and the schedule still spans 933 days against a network of 870, and the document reports what is there rather than filling a gap.'),
  ('fdp', 'intermediate', 'final', null, 31, 'The document''s roll-ups read a total CAPEX of 2250.0000 and a total OPEX of 95.0000, and a published empty ledger returns 0.0000 and 0.0000. What are the roll-ups doing?', '["Adding the cost items the ledger holds and nothing else, which is why a published example returns a CAPEX of 574.3000 with an OPEX of 0.5000.", "Taking the concept''s three capex fields of 520.0000, 1350.0000 and 380.0000, which is why the total matches the concept and an empty ledger falls back on it.", "Summing the ledger and the facility cards together, which is why the CAPEX total sits above the FPSO card''s own screening figure of 1363.3524.", "Reading the screening case, so the decommissioning provision of 260.0000 enters the OPEX total spread across the concept''s 20.0000 year life."]'::jsonb, 0, 'The ABEX line of 260.0000 is in neither total, and a published ledger of strings, blanks and unassigned phases returns a CAPEX of 12.5000 and an OPEX of 3.0000.'),
  ('fdp', 'intermediate', 'final', null, 32, 'A reviewer asks for the P90 of the FPSO card''s capex of 1363.3524 and the P90 of the register''s exposure of 269.0000 million USD. What is the answer?', '["184.6717 and 5.0000, the smallest facility capex the plan carries and the smallest contribution to the exposure, since a P90 is the low case of whatever figure is being reported.", "1363.3524 and 269.0000 themselves, since a screening figure is already a mid case and the low case of a single estimate is that estimate.", "The exposure alone carries one, at 269.0000 against cost impacts adding to 1145.0000, since an exposure is built from probabilities somebody keyed while a capex off a curve is not.", "That neither carries one, since a P label belongs to a reserves distribution one fluid at a time, and a curve output and an expected value are not distributions."]'::jsonb, 3, 'P90 is the low case of one fluid''s reserves, and a capex, a rate, a cost, a duration or an index never takes a P label at all.'),
  ('fdp', 'intermediate', 'final', null, 33, 'The same plan with no economics written reports 89 percent and the error that total CAPEX is zero or missing. What does that pair of outputs tell a reader?', '["That the economics are present but unreadable, since a section holding a zero of its own still counts toward the nine and only an unreadable one raises an error.", "That eight of nine sections rounds to 89 percent and the ninth is the risk register, whose unscored row keeps it from counting as complete.", "Which section is absent and why the plan is not valid, since the percentage counts the sections carrying something and the error names the one that does not.", "That the plan should be re-run on the concept''s capex of 2250.0000, which the engine substitutes whenever the cost ledger carries no total."]'::jsonb, 2, 'Nothing is substituted quietly: the plan carrying no economics reports 89 percent and names the missing total rather than reading 2250.0000 off the concept.'),
  ('fdp', 'intermediate', 'final', null, 34, 'EGINA''s network returns 870 days and the dates typed on the same eight activities span 933. What are the 63 days between them?', '["Contingency somebody set aside, which the engine holds back from the critical path so a slip on a1, a3, a4 or a7 can be absorbed before first oil moves.", "Contingency already spent, room the dates leave the work that no activity asked for, and it belongs to no activity as the 480 days on subsea installation does.", "The float of detailed engineering and topsides fabrication counted once each, since 180 and 180 overlap and only the part outside the path reaches the calendar.", "A counting difference, since the network measures from day 0 while the calendar counts both ends of the window, adding a day for each milestone."]'::jsonb, 1, '870 comes from durations and links with no date taking part, 933 from the earliest typed date to the latest with no duration taking part, and nothing reconciles them.'),
  ('fdp', 'intermediate', 'final', null, 35, 'The Egina FPSO card reads a capex of 1363.3524 and the four well campaign reads 141050000. What is the relationship between those two figures?', '["Both are money in different notations, plan money in million USD to four decimals and well costs in whole currency units, and neither converts by moving a decimal.", "The campaign is the drilling share of the facility''s own capex, which is why the concept carries a drilling field of 520.0000 inside a total capex of 2250.0000 million USD.", "The card''s figure is the annual cost of running the vessel and the campaign a one off charge, so the two are compared over the concept''s own life of 20.0000 years.", "The campaign is a costed number and the card a screening one, so the campaign is the larger of the two once both are read in one unit."]'::jsonb, 0, '141050000 USD is 141.0500 million USD, well under the card''s 1363.3524, and the plan''s drilling cost item of 520.0000 is a third estimate of overlapping work.'),
  ('fdp', 'intermediate', 'final', null, 36, 'The Deep tie-back''s flow assurance score of 3 reads Medium, and a risk register score of 3 reads Low. Which reading is wrong?', '["The flow assurance reading, since the studio carries a single risk scale and a score of 3 sits below the Medium threshold of 6 on every surface in the studio it appears on.", "The register reading, since a hazard list naming Hydrates High outranks a band computed from probability and impact and promotes the row that carries it.", "Both, since the repairs before this course put every surface onto one scale and a score of 3 now reads Low on the hazard screen as well.", "Neither, because flow assurance runs its own scale where a level is High above 5 and Medium above 2, while the register''s bands of 20, 12 and 6 measure another quantity."]'::jsonb, 3, 'The register and the HSE matrix do agree, Critical 1, High 1, Medium 1, Low 1 and Unscored 1 on both, because they share one scale; the hazard screen never did.'),
  ('fdp', 'intermediate', 'final', null, 37, 'Subsea tie-in slips is a Schedule risk banded Critical at 20, while subsea installation carries 480 days of float in the network. What does the register know about that float?', '["It reads the float and prices it, which is why the Schedule source row carries the largest scored contribution to the register''s exposure at 108.0000 million USD.", "It reads the critical path alone, so a risk naming an activity that carries float is banded one step below the same risk sitting on a1, a3, a4 or a7 instead.", "Nothing at all, because a band is a probability times an impact that somebody typed, and the register reads no early start, no late start and no critical path.", "It reads the calendar span of 933 days instead of the float, which is how a Schedule risk reads Critical while the work has 63 days of room."]'::jsonb, 2, 'Hull conversion and integration sit at float 0 and subsea installation carries 480 days, and none of that reaches a register scored 4 times 5.'),
  ('fdp', 'intermediate', 'final', null, 38, 'The four well campaign is 182 rig days of work and 95 days of elapsed time on two rigs. Which figure could be typed as a duration in the activity network, and what still would not follow?', '["The rig days, since a network is built from the work rather than from the calendar, and the layout''s 95 days is a presentation of the same 182.", "The campaign days, since a duration is elapsed whole days, and the network would still know nothing of rig moves, a rig free only from a date, or an injector needed down first.", "Neither, since a drilling campaign is priced rather than scheduled and the network reads its durations only from the eight activities the plan carries.", "Both, since 182 on one rig and 95 on two are one activity at two resourcings, and the forward pass takes the later of the two figures."]'::jsonb, 1, 'Those constraints belong in the network where a link can be typed between two activities, and the layout answers only how much elapsed time this much drilling occupies.'),
  ('fdp', 'intermediate', 'final', null, 39, 'The document reports a total CAPEX of 2250.0000 while the FPSO card carries 1363.3524 and the concept''s facilities field carries 1350.0000. What should a reader do with three numbers describing overlapping things?', '["Hold all three and ask what each was measured against, since the ledger totals line by line, the concept carries three capex fields, and the card is a curve on a type and a nameplate.", "Take the card''s figure, since it is the only one derived rather than typed and the other two are entries somebody may well have left stale.", "Average them, since each estimates the same vessel at a different stage and the mean of three estimates is the screening tier''s own answer.", "Take the concept''s field of 1350.0000, since the scenario economics read the card only when a concept''s facilities capex is missing."]'::jsonb, 0, 'The studio shows all three rather than picking one, and reconciling them is planning work while averaging them or deleting the inconvenient one is not.'),
  ('fdp', 'intermediate', 'final', null, 40, 'A register row with no probability reads Unscored, and an activity with no readable dates returns a calendar span of null. What do those two answers have in common?', '["Each is a documented default, since an unscored risk is banded Low and an undated activity is dated from the concept''s own start date, so both plans still compute cleanly.", "Each halts the calculation and names the field that was left empty, in the way a concept with no capex is refused and a price deck short of a year is refused by name.", "Each is rounded to the nearest reportable value, so an empty schedule and an unreadable one both read 0 and the exposure still reads 269.0000.", "Each reports an absence as an absence: the unscored row adds 0.0000 to an exposure of 269.0000 and leaves health at 58, and a null span says the extent is unknown."]'::jsonb, 3, 'Before the repairs an unscored risk counted as Low, which raised health because health averages across the scored rows, so a register improved when a probability was left blank.'),
  ('fdp', 'intermediate', 'final', null, 41, 'The document reports completeness at 100 percent with HSE and Risks both present, while the register reads health 58, exposure 269.0000 and one unscored row. What is the relationship?', '["Health feeds completeness, so a section counts as present only when its own health clears 50, which the register''s 58 does with room to spare.", "The unscored row is what holds completeness below the full mark, since nine of nine sections would otherwise report and the plan reads 89 percent.", "Completeness counts a section as filled and says nothing about what is in it, so a register whose headline figures are incomplete by exactly one row still scores its section present.", "Exposure is the money form of completeness, so 269.0000 against cost impacts of 1145.0000 is the share of the register that has been filled in."]'::jsonb, 2, 'Health 58, exposure 269.0000 and one unscored row are three separate readings, and the document carries the section as present either way.'),
  ('fdp', 'intermediate', 'final', null, 42, 'The plan''s peak of 60.0000 kbpd fills the Egina FPSO''s nameplate exactly at an oil utilisation of 1.000000, and the plan carries four wells taking 182 rig days. What does that utilisation assume about the wells?', '["That the four wells deliver the nameplate, since the engine divides the peak across the producers and flags a bottleneck when one cannot carry its share.", "That the campaign finishes before first oil, since a utilisation of 1.000000 is reported only once the wells have been dated against the schedule network.", "That three of the four are producers, since EG-03 is a water injector and its 42 days are excluded from the throughput the ratio is measured against.", "Nothing at all, since the throughput is the plan''s own peak and the gas that follows from a gas-oil ratio of 640 scf a barrel, and no well count, depth or trajectory enters it."]'::jsonb, 3, 'One numerator and three denominators: 60000 bopd against each nameplate, so the FPSO reads 1.000000 and the debottlenecked case 0.400000 on the same production.');
